{
  "name": "SafeTrack - Church Donation Vault",
  "description": "A secure, local-first application for church treasurers to manage donations, batches, and givers with AI-powered insights."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Fund {
  General = 'General',
  Benevolent = 'Benevolent',
  Missions = 'Missions',
  Building = 'Building',
  Youth = 'Youth',
  Internal = 'Internal'
}

export enum PaymentMethod {
  Cash = 'Cash',
  Check = 'Check',
  ETransfer = 'E-Transfer'
}

export enum BatchStatus {
  Open = 'Open',
  Finalized = 'Finalized'
}

export interface Giver {
  id?: number;
  envelopeNumber: number;
  name: string;
  email?: string;
  address?: string;
}

export interface DonationSplit {
  fund: Fund;
  amount: number;
}

export interface Donation {
  id?: number;
  giverId: number;
  batchId: number;
  amount: number; // Total amount of donation
  date: string;
  paymentMethod: PaymentMethod;
  splits: DonationSplit[];
  notes?: string;
}

export interface Batch {
  id?: number;
  batchNumber: string;
  date: string;
  status: BatchStatus;
  totalAmount: number;
  itemCount: number;
}

export interface AppSettings {
  id?: number;
  nextEnvelopeNumber: number;
}

import Dexie, { Table } from 'dexie';
import { Giver, Batch, Donation, AppSettings } from '../types';

class ChurchDatabase extends Dexie {
  givers!: Table<Giver, number>;
  batches!: Table<Batch, number>;
  donations!: Table<Donation, number>;
  settings!: Table<AppSettings, number>;

  constructor() {
    super('SafeTrackDB');
    this.version(1).stores({
      givers: '++id, envelopeNumber, name',
      batches: '++id, batchNumber, date, status',
      donations: '++id, giverId, batchId, date',
      settings: '++id'
    });
  }
}

export const db = new ChurchDatabase();

// Initial Setup Helper
export const initDatabase = async () => {
  const count = await db.settings.count();
  if (count === 0) {
    await db.settings.add({ nextEnvelopeNumber: 100 });
  }
};

export const getNextEnvelopeNumber = async (): Promise<number> => {
  const setting = await db.settings.orderBy('id').first();
  return setting?.nextEnvelopeNumber || 100;
};

export const incrementEnvelopeNumber = async () => {
  const setting = await db.settings.orderBy('id').first();
  if (setting && setting.id) {
    await db.settings.update(setting.id, { nextEnvelopeNumber: setting.nextEnvelopeNumber + 1 });
  }
};

export const exportData = async (): Promise<string> => {
  const allGivers = await db.givers.toArray();
  const allBatches = await db.batches.toArray();
  const allDonations = await db.donations.toArray();
  const allSettings = await db.settings.toArray();

  return JSON.stringify({ givers: allGivers, batches: allBatches, donations: allDonations, settings: allSettings });
};

export const importData = async (jsonString: string) => {
  const data = JSON.parse(jsonString);
  await db.transaction('rw', db.givers, db.batches, db.donations, db.settings, async () => {
    await db.givers.clear();
    await db.batches.clear();
    await db.donations.clear();
    await db.settings.clear();

    if(data.givers) await db.givers.bulkAdd(data.givers);
    if(data.batches) await db.batches.bulkAdd(data.batches);
    if(data.donations) await db.donations.bulkAdd(data.donations);
    if(data.settings) await db.settings.bulkAdd(data.settings);
  });
};

import { GoogleGenAI } from "@google/genai";
import { Batch, Donation } from "../types";

export const generateFinancialInsight = async (
  totalValue: number, 
  totalBatches: number, 
  recentDonations: Donation[]
): Promise<string> => {
  if (!process.env.API_KEY) {
    return "AI Assistant offline. (API Key missing)";
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a helpful church treasurer assistant.
    Current Vault Stats:
    - Total Vault Value: $${totalValue.toFixed(2)}
    - Total Batches Processed: ${totalBatches}
    - Recent Donation Count: ${recentDonations.length}

    Provide a 1-sentence encouraging summary or financial tip for the treasurer based on this activity. Keep it professional yet warm.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Keep up the good work managing the funds!";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Unable to generate insights at this moment.";
  }
};

