import React, { useState, useEffect } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, getNextEnvelopeNumber, incrementEnvelopeNumber } from '../services/db';
import { UserPlus, Search, User } from 'lucide-react';

const GiverRegistry: React.FC = () => {
  const givers = useLiveQuery(() => db.givers.toArray());
  const [showModal, setShowModal] = useState(false);
  const [nextEnv, setNextEnv] = useState<number>(0);
  const [search, setSearch] = useState('');

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    address: ''
  });

  useEffect(() => {
    if (showModal) {
      getNextEnvelopeNumber().then(setNextEnv);
    }
  }, [showModal]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await db.givers.add({
      envelopeNumber: nextEnv,
      ...formData
    });
    await incrementEnvelopeNumber();
    setShowModal(false);
    setFormData({ name: '', email: '', address: '' });
  };

  const filteredGivers = givers?.filter(g => 
    g.name.toLowerCase().includes(search.toLowerCase()) || 
    g.envelopeNumber.toString().includes(search)
  );

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-bold text-gray-800">Giver Registry</h2>
          <p className="text-gray-500">Manage church members and donors.</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-church-500 hover:bg-church-900 text-white px-6 py-3 rounded-2xl shadow-lg flex items-center gap-2 transition-all font-semibold"
        >
          <UserPlus className="w-5 h-5" />
          Register New Giver
        </button>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <Search className="absolute left-4 top-3.5 text-gray-400 w-5 h-5" />
        <input 
          type="text" 
          placeholder="Search by name or envelope #..." 
          className="w-full pl-12 pr-4 py-3 rounded-2xl border-none shadow-md focus:ring-2 focus:ring-church-500"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {/* Giver Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredGivers?.map(giver => (
          <div key={giver.id} className="bg-white p-5 rounded-3xl shadow-md hover:shadow-xl transition-shadow border border-gray-100">
             <div className="flex justify-between items-start mb-4">
                <div className="w-12 h-12 bg-church-900 rounded-2xl flex items-center justify-center text-white font-bold text-lg">
                  {giver.envelopeNumber}
                </div>
                <div className="p-2 bg-gray-50 rounded-full">
                  <User className="w-5 h-5 text-gray-400" />
                </div>
             </div>
             <h3 className="text-lg font-bold text-gray-800">{giver.name}</h3>
             <p className="text-sm text-gray-500 truncate">{giver.email || "No email"}</p>
             <p className="text-sm text-gray-400 mt-2 truncate">{giver.address || "No address on file"}</p>
          </div>
        ))}
      </div>

      {/* Add Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl">
            <h3 className="text-2xl font-bold mb-6 text-gray-800">Register Giver</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="bg-blue-50 p-4 rounded-xl mb-4">
                <label className="text-xs font-bold text-church-900 uppercase">Assigned Envelope #</label>
                <div className="text-3xl font-bold text-church-500">{nextEnv}</div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                <input 
                  required
                  className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-church-500"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Email (Optional)</label>
                <input 
                  type="email"
                  className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-church-500"
                  value={formData.email}
                  onChange={e => setFormData({...formData, email: e.target.value})}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Address (Optional)</label>
                <input 
                  className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-church-500"
                  value={formData.address}
                  onChange={e => setFormData({...formData, address: e.target.value})}
                />
              </div>

              <div className="flex gap-4 mt-6">
                <button 
                  type="button" 
                  onClick={() => setShowModal(false)}
                  className="flex-1 py-3 text-gray-500 font-semibold hover:bg-gray-100 rounded-xl transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  className="flex-1 py-3 bg-church-900 text-white font-semibold rounded-xl hover:bg-blue-800 transition-colors shadow-lg"
                >
                  Save to Vault
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default GiverRegistry;

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { Fund, PaymentMethod, BatchStatus } from '../types';
import { Plus, Save, Trash2, AlertCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

interface Row {
  id: number;
  envelope: string;
  name: string;
  amount: string;
  method: PaymentMethod;
  fund: Fund;
  error?: string;
}

const BatchEntry: React.FC = () => {
  const navigate = useNavigate();
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [rows, setRows] = useState<Row[]>([
    { id: Date.now(), envelope: '', name: '', amount: '', method: PaymentMethod.Check, fund: Fund.General }
  ]);

  const updateRow = (id: number, field: keyof Row, value: any) => {
    setRows(prev => prev.map(row => {
      if (row.id === id) {
        return { ...row, [field]: value, error: undefined };
      }
      return row;
    }));
  };

  const lookupGiver = async (id: number, envelopeStr: string) => {
    const envelope = parseInt(envelopeStr);
    if (isNaN(envelope)) return;

    // Simple handling for loose offering
    if (envelope === 0) {
      updateRow(id, 'name', 'Loose Offering');
      return;
    }

    const giver = await db.givers.where('envelopeNumber').equals(envelope).first();
    updateRow(id, 'name', giver ? giver.name : 'Unknown Giver');
    if (!giver) {
      setRows(prev => prev.map(r => r.id === id ? { ...r, error: 'Env # not found' } : r));
    }
  };

  const addRow = () => {
    setRows([...rows, { id: Date.now(), envelope: '', name: '', amount: '', method: PaymentMethod.Check, fund: Fund.General }]);
  };

  const removeRow = (id: number) => {
    if (rows.length > 1) {
      setRows(rows.filter(r => r.id !== id));
    }
  };

  const calculateTotal = () => {
    return rows.reduce((sum, row) => sum + (parseFloat(row.amount) || 0), 0);
  };

  const handleSave = async () => {
    // Basic validation
    if (rows.some(r => r.error || !r.envelope || !r.amount)) {
      alert("Please fix errors or fill incomplete rows before saving.");
      return;
    }

    const total = calculateTotal();
    const batchId = await db.batches.add({
      batchNumber: `B-${Date.now()}`,
      date: date,
      status: BatchStatus.Open,
      totalAmount: total,
      itemCount: rows.length
    });

    // Create donations
    for (const row of rows) {
      let giverId = 0; // Default for loose offering
      const giver = await db.givers.where('envelopeNumber').equals(parseInt(row.envelope)).first();
      if (giver && giver.id) giverId = giver.id;

      await db.donations.add({
        giverId,
        batchId: batchId as number,
        amount: parseFloat(row.amount),
        date: date,
        paymentMethod: row.method,
        splits: [{ fund: row.fund, amount: parseFloat(row.amount) }]
      });
    }

    navigate('/history');
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-bold text-gray-800">New Batch Entry</h2>
          <p className="text-gray-500">Fast entry mode.</p>
        </div>
        <div className="bg-church-900 text-white px-6 py-2 rounded-xl text-right">
          <p className="text-xs uppercase opacity-70">Batch Total</p>
          <p className="text-2xl font-bold">${calculateTotal().toFixed(2)}</p>
        </div>
      </div>

      <div className="bg-white p-4 rounded-3xl shadow-xl flex-1 flex flex-col overflow-hidden">
        <div className="flex gap-4 mb-4 items-center border-b pb-4">
          <label className="font-bold text-gray-700">Batch Date:</label>
          <input 
            type="date" 
            value={date} 
            onChange={(e) => setDate(e.target.value)}
            className="border-gray-300 border rounded-lg p-2"
          />
        </div>

        <div className="flex-1 overflow-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50 sticky top-0 z-10">
              <tr>
                <th className="p-3 text-sm font-bold text-gray-600 rounded-tl-xl">Env #</th>
                <th className="p-3 text-sm font-bold text-gray-600">Giver Name</th>
                <th className="p-3 text-sm font-bold text-gray-600">Amount</th>
                <th className="p-3 text-sm font-bold text-gray-600">Method</th>
                <th className="p-3 text-sm font-bold text-gray-600">Fund</th>
                <th className="p-3 text-sm font-bold text-gray-600 rounded-tr-xl">Action</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={row.id} className="border-b last:border-0 hover:bg-blue-50/30 transition-colors">
                  <td className="p-2">
                    <div className="relative">
                      <input 
                        className={`w-20 p-2 rounded-lg border ${row.error ? 'border-red-500 bg-red-50' : 'border-gray-200'}`}
                        value={row.envelope}
                        onChange={(e) => updateRow(row.id, 'envelope', e.target.value)}
                        onBlur={(e) => lookupGiver(row.id, e.target.value)}
                        placeholder="101"
                        autoFocus={rows.length > 1 && rows[rows.length - 1].id === row.id}
                      />
