import React, { useState } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db } from '../services/db';
import { BatchStatus } from '../types';
import { FileText, Calculator, Lock, CheckCircle } from 'lucide-react';

const BatchHistory: React.FC = () => {
  const batches = useLiveQuery(() => db.batches.orderBy('date').reverse().toArray());
  const [selectedBatch, setSelectedBatch] = useState<number | null>(null);

  // Cash Counter State
  const [cashCounts, setCashCounts] = useState<Record<string, number>>({
    '100': 0, '50': 0, '20': 0, '10': 0, '5': 0, '1': 0, '0.25': 0, '0.10': 0, '0.05': 0, '0.01': 0
  });

  const activeBatch = batches?.find(b => b.id === selectedBatch);

  const calculateCashTotal = () => {
    return Object.entries(cashCounts).reduce((acc, [denom, count]) => {
      return acc + (parseFloat(denom) * count);
    }, 0);
  };

  const finalizeBatch = async (id: number) => {
    if (confirm("Are you sure? Once finalized, a batch cannot be edited.")) {
      await db.batches.update(id, { status: BatchStatus.Finalized });
    }
  };

  return (
    <div className="space-y-6">
      <h2 className="text-3xl font-bold text-gray-800">Batch History</h2>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* List */}
        <div className="lg:col-span-1 space-y-4">
          {batches?.map(batch => (
            <div 
              key={batch.id} 
              onClick={() => setSelectedBatch(batch.id || null)}
              className={`p-4 rounded-2xl cursor-pointer border transition-all ${
                selectedBatch === batch.id 
                  ? 'bg-church-900 text-white shadow-xl scale-105' 
                  : 'bg-white hover:bg-blue-50 border-gray-200'
              }`}
            >
              <div className="flex justify-between items-center mb-2">
                <span className="font-bold">Batch #{batch.id}</span>
                <span className={`text-xs px-2 py-1 rounded-full ${
                  batch.status === BatchStatus.Finalized ? 'bg-green-400/20 text-green-400' : 'bg-yellow-400/20 text-yellow-500'
                }`}>
                  {batch.status}
                </span>
              </div>
              <div className="flex justify-between text-sm opacity-80">
                <span>{new Date(batch.date).toLocaleDateString()}</span>
                <span className="font-mono">${batch.totalAmount.toFixed(2)}</span>
              </div>
            </div>
          ))}
          {(!batches || batches.length === 0) && <p className="text-gray-400">No batches found.</p>}
        </div>

        {/* Details / Cash Counter */}
        <div className="lg:col-span-2">
          {activeBatch ? (
            <div className="bg-white rounded-3xl shadow-xl p-8 border border-gray-100">
               <div className="flex justify-between items-start mb-6">
                 <div>
                   <h3 className="text-2xl font-bold text-gray-800">Batch Audit: #{activeBatch.id}</h3>
                   <p className="text-gray-500">Total Recorded: <span className="font-bold text-church-900">${activeBatch.totalAmount.toFixed(2)}</span></p>
                 </div>
                 {activeBatch.status === BatchStatus.Open && (
                   <button 
                    onClick={() => finalizeBatch(activeBatch.id!)}
                    className="flex items-center gap-2 bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded-xl shadow-lg transition-colors"
                   >
                     <Lock className="w-4 h-4" /> Finalize
                   </button>
                 )}
                 {activeBatch.status === BatchStatus.Finalized && (
                   <div className="flex items-center gap-2 text-green-600 bg-green-100 px-4 py-2 rounded-xl">
                     <CheckCircle className="w-5 h-5" /> Locked
                   </div>
                 )}
               </div>

               <div className="bg-gray-50 p-6 rounded-2xl">
                 <h4 className="font-bold text-gray-700 flex items-center gap-2 mb-4">
                   <Calculator className="w-5 h-5 text-church-500" /> Cash Counter Utility
                 </h4>

                 <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                   {[100, 50, 20, 10, 5].map(denom => (
                     <div key={denom}>
                       <label className="text-xs font-bold text-gray-400 block mb-1">${denom}</label>
                       <input 
                         type="number" 
                         min="0"
                         className="w-full p-2 rounded-lg border border-gray-200 text-center"
                         value={cashCounts[denom.toString()] || ''}
                         onChange={(e) => setCashCounts({...cashCounts, [denom.toString()]: parseInt(e.target.value) || 0})}
                       />
                     </div>
                   ))}
                 </div>
                 <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mt-4">
                   {[1, 0.25, 0.10, 0.05, 0.01].map(denom => (
                     <div key={denom}>
                       <label className="text-xs font-bold text-gray-400 block mb-1">${denom}</label>
                       <input 
                         type="number" 
                         min="0"
                         className="w-full p-2 rounded-lg border border-gray-200 text-center"
                         value={cashCounts[denom.toString()] || ''}
                         onChange={(e) => setCashCounts({...cashCounts, [denom.toString()]: parseInt(e.target.value) || 0})}
                       />
                     </div>
                   ))}
                 </div>

                 <div className="mt-6 p-4 bg-white rounded-xl border border-gray-200 flex justify-between items-center">
