import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { Fund, PaymentMethod, BatchStatus } from '../types';
import { Plus, Save, Trash2, AlertCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

interface Row {
  id: number;
  envelope: string;
  name: string;
  amount: string;
  method: PaymentMethod;
  fund: Fund;
  error?: string;
}

const BatchEntry: React.FC = () => {
  const navigate = useNavigate();
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [rows, setRows] = useState<Row[]>([
    { id: Date.now(), envelope: '', name: '', amount: '', method: PaymentMethod.Check, fund: Fund.General }
  ]);

  const updateRow = (id: number, field: keyof Row, value: any) => {
    setRows(prev => prev.map(row => {
      if (row.id === id) {
        return { ...row, [field]: value, error: undefined };
      }
      return row;
    }));
  };

  const lookupGiver = async (id: number, envelopeStr: string) => {
    const envelope = parseInt(envelopeStr);
    if (isNaN(envelope)) return;

    // Simple handling for loose offering
    if (envelope === 0) {
      updateRow(id, 'name', 'Loose Offering');
      return;
    }

    const giver = await db.givers.where('envelopeNumber').equals(envelope).first();
    updateRow(id, 'name', giver ? giver.name : 'Unknown Giver');
    if (!giver) {
      setRows(prev => prev.map(r => r.id === id ? { ...r, error: 'Env # not found' } : r));
    }
  };

  const addRow = () => {
    setRows([...rows, { id: Date.now(), envelope: '', name: '', amount: '', method: PaymentMethod.Check, fund: Fund.General }]);
  };

  const removeRow = (id: number) => {
    if (rows.length > 1) {
      setRows(rows.filter(r => r.id !== id));
    }
  };

  const calculateTotal = () => {
    return rows.reduce((sum, row) => sum + (parseFloat(row.amount) || 0), 0);
  };

  const handleSave = async () => {
    // Basic validation
    if (rows.some(r => r.error || !r.envelope || !r.amount)) {
      alert("Please fix errors or fill incomplete rows before saving.");
      return;
    }

    const total = calculateTotal();
    const batchId = await db.batches.add({
      batchNumber: `B-${Date.now()}`,
      date: date,
      status: BatchStatus.Open,
      totalAmount: total,
      itemCount: rows.length
    });

    // Create donations
    for (const row of rows) {
      let giverId = 0; // Default for loose offering
      const giver = await db.givers.where('envelopeNumber').equals(parseInt(row.envelope)).first();
      if (giver && giver.id) giverId = giver.id;

      await db.donations.add({
        giverId,
        batchId: batchId as number,
        amount: parseFloat(row.amount),
        date: date,
        paymentMethod: row.method,
        splits: [{ fund: row.fund, amount: parseFloat(row.amount) }]
      });
    }

    navigate('/history');
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-bold text-gray-800">New Batch Entry</h2>
          <p className="text-gray-500">Fast entry mode.</p>
        </div>
        <div className="bg-church-900 text-white px-6 py-2 rounded-xl text-right">
          <p className="text-xs uppercase opacity-70">Batch Total</p>
          <p className="text-2xl font-bold">${calculateTotal().toFixed(2)}</p>
        </div>
      </div>

      <div className="bg-white p-4 rounded-3xl shadow-xl flex-1 flex flex-col overflow-hidden">
        <div className="flex gap-4 mb-4 items-center border-b pb-4">
          <label className="font-bold text-gray-700">Batch Date:</label>
          <input 
            type="date" 
            value={date} 
            onChange={(e) => setDate(e.target.value)}
            className="border-gray-300 border rounded-lg p-2 bg-gray-50"
          />
        </div>

        <div className="flex-1 overflow-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50 sticky top-0 z-10">
              <tr>
                <th className="p-3 text-sm font-bold text-gray-600 rounded-tl-xl">Env #</th>
                <th className="p-3 text-sm font-bold text-gray-600">Giver Name</th>
                <th className="p-3 text-sm font-bold text-gray-600">Amount</th>
                <th className="p-3 text-sm font-bold text-gray-600">Method</th>
                <th className="p-3 text-sm font-bold text-gray-600">Fund</th>
                <th className="p-3 text-sm font-bold text-gray-600 rounded-tr-xl">Action</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={row.id} className="border-b last:border-0 hover:bg-blue-50/30 transition-colors">
                  <td className="p-2">
                    <div className="relative">
                      <input 
                        className={`w-20 p-2 rounded-lg border ${row.error ? 'border-red-500 bg-red-50' : 'border-gray-200 bg-gray-50'}`}
                        value={row.envelope}
                        onChange={(e) => updateRow(row.id, 'envelope', e.target.value)}
                        onBlur={(e) => lookupGiver(row.id, e.target.value)}
                        placeholder="101"
                        autoFocus={rows.length > 1 && rows[rows.length - 1].id === row.id}
                      />
                      {row.error && <AlertCircle className="w-4 h-4 text-red-500 absolute right-2 top-3" />}
                    </div>
                  </td>
                  <td className="p-2">
                    <input 
                      disabled 
                      className="w-full bg-transparent font-medium text-gray-700" 
                      value={row.name} 
                      placeholder="Enter Env #"
                    />
                  </td>
                  <td className="p-2">
                    <input 
                      type="number"
                      step="0.01"
                      className="w-28 p-2 rounded-lg border border-gray-200 bg-gray-50"
                      value={row.amount}
                      onChange={(e) => updateRow(row.id, 'amount', e.target.value)}
                      placeholder="0.00"
                    />
                  </td>
                  <td className="p-2">
                    <select 
                      className="p-2 rounded-lg border border-gray-200 bg-gray-50"
                      value={row.method}
                      onChange={(e) => updateRow(row.id, 'method', e.target.value)}
                    >
                      {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                  </td>
                  <td className="p-2">
                    <select 
                      className="p-2 rounded-lg border border-gray-200 bg-gray-50"
                      value={row.fund}
                      onChange={(e) => updateRow(row.id, 'fund', e.target.value)}
                    >
                      {Object.values(Fund).map(f => <option key={f} value={f}>{f}</option>)}
                    </select>
                  </td>
                  <td className="p-2">
                    <button 
                      onClick={() => removeRow(row.id)}
                      className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="p-4 border-t flex justify-between items-center bg-gray-50 rounded-b-3xl mt-2">
          <button 
            onClick={addRow}
            className="flex items-center gap-2 text-church-900 font-bold hover:bg-white px-4 py-2 rounded-xl transition-colors"
          >
            <Plus className="w-5 h-5" /> Add Row
          </button>
          <button 
            onClick={handleSave}
            className="bg-church-gold hover:bg-yellow-400 text-church-900 px-8 py-3 rounded-xl font-bold shadow-lg flex items-center gap-2 transition-transform active:scale-95"
          >
            <Save className="w-5 h-5" /> Save Batch to Vault
          </button>
        </div>
      </div>
    </div>
  );
};

export default BatchEntry;

import React, { useState } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db } from '../services/db';
