import React, { useState } from 'react';
import { exportData, importData, db } from '../services/db';
import { Download, Upload, RefreshCw, AlertTriangle } from 'lucide-react';
import { useLiveQuery } from 'dexie-react-hooks';

const Settings: React.FC = () => {
  const [backupUrl, setBackupUrl] = useState<string | null>(null);
  const settings = useLiveQuery(() => db.settings.orderBy('id').first());

  const handleBackup = async () => {
    const json = await exportData();
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    setBackupUrl(url);
  };

  const handleRestore = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if(!confirm("WARNING: This will overwrite all current data. Proceed?")) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const json = event.target?.result as string;
      try {
        await importData(json);
        alert("Restore successful! Reloading...");
        window.location.reload();
      } catch (err) {
        alert("Error restoring data. Invalid file format.");
      }
    };
    reader.readAsText(file);
  };

  const updateEnvelope = async (val: string) => {
    const num = parseInt(val);
    if (settings && settings.id && !isNaN(num)) {
      await db.settings.update(settings.id, { nextEnvelopeNumber: num });
    }
  };

  return (
    <div className="space-y-8 max-w-4xl mx-auto">
      <h2 className="text-3xl font-bold text-gray-800">Admin Settings</h2>

      <div className="bg-white p-8 rounded-3xl shadow-xl border border-gray-100">
        <h3 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <RefreshCw className="w-5 h-5 text-church-500" /> System Configuration
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Next Auto-Increment Envelope #</label>
            <input 
              type="number" 
              className="w-full p-4 rounded-xl border border-gray-200 text-2xl font-bold text-church-900 focus:ring-2 focus:ring-church-500 bg-gray-50"
              value={settings?.nextEnvelopeNumber || 100}
              onChange={(e) => updateEnvelope(e.target.value)}
            />
            <p className="text-xs text-gray-400 mt-2">Will be used for the next new giver registration.</p>
          </div>
        </div>
      </div>

      <div className="bg-gradient-to-br from-gray-900 to-church-900 p-8 rounded-3xl shadow-xl text-white">
        <h3 className="text-xl font-bold mb-6 flex items-center gap-2">
          <AlertTriangle className="w-5 h-5 text-yellow-500" /> Data Management
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="bg-white/10 p-6 rounded-2xl backdrop-blur-sm">
            <h4 className="font-bold text-lg mb-2">Backup Vault</h4>
            <p className="text-sm text-gray-300 mb-4">Export all data (Givers, Donations, Batches) to a secure JSON file.</p>
            <button 
              onClick={handleBackup}
              className="w-full bg-church-gold text-church-900 font-bold py-3 rounded-xl hover:bg-yellow-400 transition-colors flex justify-center gap-2 items-center"
            >
              <Download className="w-5 h-5" /> Generate Backup
            </button>
            {backupUrl && (
              <a 
                href={backupUrl} 
                download={`safetrack_backup_${new Date().toISOString().split('T')[0]}.json`}
                className="block mt-3 text-center text-sm text-green-300 underline"
              >
                Click here to download file
              </a>
            )}
          </div>

          <div className="bg-white/10 p-6 rounded-2xl backdrop-blur-sm border border-red-500/30">
            <h4 className="font-bold text-lg mb-2">Restore Vault</h4>
            <p className="text-sm text-gray-300 mb-4">Overwrite current database with a backup file. <span className="text-red-300">Irreversible.</span></p>
            <label className="w-full bg-red-900/50 text-red-200 border border-red-500/50 font-bold py-3 rounded-xl hover:bg-red-900 transition-colors flex justify-center gap-2 items-center cursor-pointer">
              <Upload className="w-5 h-5" /> Upload Backup File
              <input type="file" onChange={handleRestore} className="hidden" accept=".json" />
            </label>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { Lock, Shield } from 'lucide-react';

interface Props {
  onUnlock: () => void;
}

const LockScreen: React.FC<Props> = ({ onUnlock }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);
  const [isSetup, setIsSetup] = useState(false);

  useEffect(() => {
    // Check if a password exists in localStorage (simulate persisted local config)
    const stored = localStorage.getItem('vault_password');
    if (!stored) {
      setIsSetup(true);
    }
  }, []);

  const handleAttempt = (e: React.FormEvent) => {
    e.preventDefault();
    const stored = localStorage.getItem('vault_password');

    if (isSetup) {
      localStorage.setItem('vault_password', password);
      sessionStorage.setItem('vault_unlocked', 'true');
      onUnlock();
    } else {
      if (password === stored) {
        sessionStorage.setItem('vault_unlocked', 'true');
        onUnlock();
      } else {
        setError(true);
        setPassword('');
      }
    }
  };

  return (
    <div className="min-h-screen bg-church-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl text-center animate-fade-in-up">
        <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6">
          <Shield className="w-10 h-10 text-church-900" />
        </div>

        <h1 className="text-2xl font-bold text-gray-800 mb-2">SafeTrack Vault</h1>
        <p className="text-gray-500 mb-8">
          {isSetup ? "Create a Vault Password to secure local data." : "Enter Password to Open Safe."}
        </p>

        <form onSubmit={handleAttempt} className="space-y-4">
          <div className="relative">
            <Lock className="absolute left-4 top-3.5 text-gray-400 w-5 h-5" />
            <input 
              type="password" 
              value={password}
              onChange={(e) => { setPassword(e.target.value); setError(false); }}
              className={`w-full pl-12 pr-4 py-3 rounded-xl border ${error ? 'border-red-500 bg-red-50' : 'border-gray-200 bg-gray-50'} focus:ring-2 focus:ring-church-500 outline-none transition-all`}
              placeholder="Vault Password"
              autoFocus
            />
          </div>

          <button 
            type="submit" 
            className="w-full bg-church-gold hover:bg-yellow-400 text-church-900 font-bold py-3 rounded-xl transition-transform active:scale-95 shadow-lg"
          >
            {isSetup ? "Set Password & Enter" : "Unlock Vault"}
          </button>
        </form>

        {error && <p className="text-red-500 mt-4 text-sm font-semibold">Incorrect Password. Access Denied.</p>}

        <p className="mt-8 text-xs text-gray-400">
          Local-first secure storage. No data leaves this device without your action.
        </p>
      </div>
    </div>
  );
};

export default LockScreen;

import Dexie, { type Table } from 'dexie';
import { Giver, Batch, Donation, AppSettings } from '../types';

class ChurchDatabase extends Dexie {
  givers!: Table<Giver, number>;
  batches!: Table<Batch, number>;
  donations!: Table<Donation, number>;
  settings!: Table<AppSettings, number>;

  constructor() {
    super('SafeTrackDB');
    this.version(1).stores({
      givers: '++id, envelopeNumber, name',
      batches: '++id, batchNumber, date, status',
      donations: '++id, giverId, batchId, date',
      settings: '++id'
    });
  }
}

export const db = new ChurchDatabase();

// Initial Setup Helper
export const initDatabase = async () => {
  const count = await db.settings.count();
  if (count === 0) {
    await db.settings.add({ nextEnvelopeNumber: 100 });
  }
};

export const getNextEnvelopeNumber = async (): Promise<number> => {
  const setting = await db.settings.orderBy('id').first();
  return setting?.nextEnvelopeNumber || 100;
};

export const incrementEnvelopeNumber = async () => {
  const setting = await db.settings.orderBy('id').first();
  if (setting && setting.id) {
    await db.settings.update(setting.id, { nextEnvelopeNumber: setting.nextEnvelopeNumber + 1 });
  }
};

export const exportData = async (): Promise<string> => {
  const allGivers = await db.givers.toArray();
  const allBatches = await db.batches.toArray();
  const allDonations = await db.donations.toArray();
  const allSettings = await db.settings.toArray();

  return JSON.stringify({ givers: allGivers, batches: allBatches, donations: allDonations, settings: allSettings });
};

export const importData = async (jsonString: string) => {
  const data = JSON.parse(jsonString);
  await db.transaction('rw', db.givers, db.batches, db.donations, db.settings, async () => {
    await db.givers.clear();
    await db.batches.clear();
    await db.donations.clear();
    await db.settings.clear();

    if(data.givers) await db.givers.bulkAdd(data.givers);
    if(data.batches) await db.batches.bulkAdd(data.batches);
    if(data.donations) await db.donations.bulkAdd(data.donations);
    if(data.settings) await db.settings.bulkAdd(data.settings);
  });
};

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../services/db';
import { Fund, PaymentMethod, BatchStatus, DonationSplit } from '../types';
import { Plus, Save, Trash2, AlertCircle, Layers, Calculator, X, Check, Banknote } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

interface Row {
  id: number;
  envelope: string;
  name: string;
  amount: string;
  method: PaymentMethod;
  splits: DonationSplit[];
  isCashVerified?: boolean;
  error?: string;
}

const DENOMINATIONS = [100, 50, 20, 10, 5, 1, 0.25, 0.10, 0.05, 0.01];

const BatchEntry: React.FC = () => {
  const navigate = useNavigate();
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [rows, setRows] = useState<Row[]>([
    { id: Date.now(), envelope: '', name: '', amount: '', method: PaymentMethod.Check, splits: [{ fund: Fund.General, amount: 0 }] }
  ]);

  // Modal States
  const [splitModalRowId, setSplitModalRowId] = useState<number | null>(null);
  const [cashModalRowId, setCashModalRowId] = useState<number | null>(null);

  // --- Row Management ---

  const addRow = () => {
    setRows(prev => [
      ...prev, 
      { 
        id: Date.now(), 
        envelope: '', 
        name: '', 
        amount: '', 
        method: PaymentMethod.Check, 
        splits: [{ fund: Fund.General, amount: 0 }] 
      }
    ]);
  };

  const removeRow = (id: number) => {
    if (rows.length > 1) {
      setRows(rows.filter(r => r.id !== id));
    }
  };

  const updateRow = (id: number, field: keyof Row, value: any) => {
    setRows(prev => prev.map(row => {
      if (row.id === id) {
        const updated = { ...row, [field]: value, error: undefined };

        // Auto-update split if single split and amount changes
        if (field === 'amount') {
          const numAmount = parseFloat(value) || 0;
          if (updated.splits.length === 1) {
             updated.splits = [{ ...updated.splits[0], amount: numAmount }];
          }
          // Reset cash verification if amount changes
          if (updated.method === PaymentMethod.Cash) {
            updated.isCashVerified = false;
          }
        }

        return updated;
      }
      return row;
    }));
  };

  const lookupGiver = async (id: number, envelopeStr: string) => {
    const envelope = parseInt(envelopeStr);
    if (isNaN(envelope)) return;

    if (envelope === 0) {
      updateRow(id, 'name', 'Loose Giving');
      return;
    }

    const giver = await db.givers.where('envelopeNumber').equals(envelope).first();
    updateRow(id, 'name', giver ? giver.name : 'Unknown Giver');
    if (!giver) {
      setRows(prev => prev.map(r => r.id === id ? { ...r, error: 'Env # not found' } : r));
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, index: number) => {
    // Add new row on Tab from last input of last row
    if (e.key === 'Tab' && !e.shiftKey && index === rows.length - 1) {
       // We let the default tab happen, but also add a row
       // Ideally we check if we are in the last column, but simply adding a row on valid completion is good UX
       const currentRow = rows[index];
       if (currentRow.envelope && currentRow.amount) {
         // Using setTimeout to allow tab focus to move naturally if we were strictly binding input refs,
         // but here we just add the row so user can tab into it.
         addRow();
       }
    }
  };

  // --- Saving ---

  const calculateTotal = () => {
    return rows.reduce((sum, row) => sum + (parseFloat(row.amount) || 0), 0);
  };

  const handleSave = async () => {
    // Validation
    const errors: string[] = [];
    rows.forEach(r => {
      if (!r.envelope) errors.push(`Row with empty envelope.`);
      if (!parseFloat(r.amount)) errors.push(`Row for ${r.name || 'Unknown'} has 0 amount.`);

      const splitTotal = r.splits.reduce((sum, s) => sum + s.amount, 0);
      const rowAmount = parseFloat(r.amount) || 0;
      // Allow small floating point diff
      if (Math.abs(splitTotal - rowAmount) > 0.01) {
        errors.push(`Row for ${r.name} has unbalanced splits.`);
      }
    });

    if (errors.length > 0) {
      alert("Cannot Save:\n" + errors.join("\n"));
      return;
    }

    const total = calculateTotal();
    const batchId = await db.batches.add({
      batchNumber: `B-${Date.now()}`,
      date: date,
      status: BatchStatus.Open,
      totalAmount: total,
      itemCount: rows.length
    });

    for (const row of rows) {
      let giverId = 0;
      const giver = await db.givers.where('envelopeNumber').equals(parseInt(row.envelope)).first();
      if (giver && giver.id) giverId = giver.id;

      await db.donations.add({
        giverId,
        batchId: batchId as number,
        amount: parseFloat(row.amount),
        date: date,
        paymentMethod: row.method,
        splits: row.splits
      });
    }

    navigate('/history');
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-bold text-gray-800">New Batch Entry</h2>
          <p className="text-gray-500">Spreadsheet Mode</p>
        </div>
        <div className="bg-church-900 text-white px-6 py-2 rounded-xl text-right shadow-lg">
          <p className="text-xs uppercase opacity-70">Batch Total</p>
          <p className="text-2xl font-bold">${calculateTotal().toFixed(2)}</p>
        </div>
      </div>

      <div className="bg-white p-4 rounded-3xl shadow-xl flex-1 flex flex-col overflow-hidden border border-gray-100">
        <div className="flex gap-4 mb-4 items-center border-b border-gray-100 pb-4">
          <label className="font-bold text-gray-700">Batch Date:</label>
          <input 
            type="date" 
            value={date} 
            onChange={(e) => setDate(e.target.value)}
            className="border-gray-200 border rounded-lg p-2 bg-gray-50 text-gray-800"
          />
        </div>

        <div className="flex-1 overflow-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50 sticky top-0 z-10 text-gray-600">
              <tr>
                <th className="p-3 text-sm font-bold rounded-tl-xl w-24">Env #</th>
                <th className="p-3 text-sm font-bold">Giver Name</th>
                <th className="p-3 text-sm font-bold w-32">Amount</th>
                <th className="p-3 text-sm font-bold w-32">Method</th>
                <th className="p-3 text-sm font-bold">Designation</th>
                <th className="p-3 text-sm font-bold rounded-tr-xl w-20">Action</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row, index) => {
                const rowAmount = parseFloat(row.amount) || 0;
                const splitTotal = row.splits.reduce((s, split) => s + split.amount, 0);
                const isUnbalanced = Math.abs(splitTotal - rowAmount) > 0.01;

                return (
                  <tr key={row.id} className="border-b border-gray-50 last:border-0 hover:bg-blue-50/30 transition-colors group">
                    <td className="p-2 align-top">
                      <div className="relative">
                        <input 
                          className={`w-20 p-2 rounded-lg border text-sm font-medium ${row.error ? 'border-red-500 bg-red-50' : 'border-gray-200 bg-gray-50 focus:ring-2 focus:ring-church-500'} outline-none`}
                          value={row.envelope}
                          onChange={(e) => updateRow(row.id, 'envelope', e.target.value)}
                          onBlur={(e) => lookupGiver(row.id, e.target.value)}
                          placeholder="0"
                          autoFocus={index === rows.length - 1 && index > 0}
                        />
                      </div>
                    </td>
                    <td className="p-2 align-top">
                      <input 
                        disabled 
                        className="w-full bg-transparent font-medium text-gray-700 py-2" 
                        value={row.name} 
                        placeholder="--"
                      />
                    </td>
                    <td className="p-2 align-top">
                      <input 
                        type="number"
                        step="0.01"
                        className={`w-28 p-2 rounded-lg border text-sm font-bold ${isUnbalanced ? 'border-red-300 bg-red-50 text-red-600' : 'border-gray-200 bg-gray-50 text-gray-800'} focus:ring-2 focus:ring-church-500 outline-none`}
                        value={row.amount}
                        onChange={(e) => updateRow(row.id, 'amount', e.target.value)}
                        placeholder="0.00"
                      />
                    </td>
                    <td className="p-2 align-top">
                       <div className="flex gap-2">
                        <select 
                          className="p-2 rounded-lg border border-gray-200 bg-gray-50 text-sm w-full outline-none focus:ring-2 focus:ring-church-500"
                          value={row.method}
                          onChange={(e) => updateRow(row.id, 'method', e.target.value)}
                        >
                          {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                        </select>
                        {row.method === PaymentMethod.Cash && (
                          <button 
                            onClick={() => setCashModalRowId(row.id)}
                            className={`p-2 rounded-lg transition-colors ${row.isCashVerified ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400 hover:bg-church-100 hover:text-church-500'}`}
                            title="Cash Counter"
                            tabIndex={-1}
                          >
                            <Banknote className="w-4 h-4" />
                          </button>
                        )}
                       </div>
                    </td>
                    <td className="p-2 align-top">
                      <button 
                        onClick={() => setSplitModalRowId(row.id)}
                        className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium border transition-all flex items-center justify-between group-focus-within:ring-2 group-focus-within:ring-church-500 outline-none ${
                          isUnbalanced 
                            ? 'bg-red-50 border-red-200 text-red-700' 
                            : 'bg-white border-gray-200 text-gray-600 hover:border-church-500'
                        }`}
                        onKeyDown={(e) => handleKeyDown(e, index)}
                      >
                        <div className="flex items-center gap-2">
                          <Layers className="w-4 h-4 opacity-50" />
                          <span>
                            {row.splits.length === 1 && row.splits[0].fund === Fund.General 
                              ? 'General Fund' 
                              : `${row.splits.length} Fund(s)`}
                          </span>
                        </div>
                        {isUnbalanced && <AlertCircle className="w-4 h-4" />}
                      </button>
                    </td>
                    <td className="p-2 align-top text-center">
                      <button 
                        onClick={() => removeRow(row.id)}
                        className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        tabIndex={-1}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div className="p-4 border-t border-gray-100 flex justify-between items-center bg-gray-50 rounded-b-3xl mt-2">
          <button 
            onClick={addRow}
            className="flex items-center gap-2 text-church-900 font-bold hover:bg-white hover:shadow px-4 py-2 rounded-xl transition-all"
          >
            <Plus className="w-5 h-5" /> Add Row
          </button>
          <button 
            onClick={handleSave}
            className="bg-church-gold hover:bg-yellow-400 text-church-900 px-8 py-3 rounded-xl font-bold shadow-lg flex items-center gap-2 transition-transform active:scale-95"
          >
            <Save className="w-5 h-5" /> Save Batch to Vault
          </button>
        </div>
      </div>

      {/* --- Modals --- */}
      {splitModalRowId && (
        <SplitModal 
          row={rows.find(r => r.id === splitModalRowId)!} 
          onClose={() => setSplitModalRowId(null)}
          onSave={(splits) => {
             updateRow(splitModalRowId, 'splits', splits);
             setSplitModalRowId(null);
          }}
        />
      )}

      {cashModalRowId && (
        <CashModal 
          row={rows.find(r => r.id === cashModalRowId)!}
          onClose={() => setCashModalRowId(null)}
          onVerify={() => {
            updateRow(cashModalRowId, 'isCashVerified', true);
            setCashModalRowId(null);
          }}
        />
      )}
    </div>
  );
};

// --- Sub-components ---

const SplitModal: React.FC<{ row: Row, onClose: () => void, onSave: (s: DonationSplit[]) => void }> = ({ row, onClose, onSave }) => {
  const [splits, setSplits] = useState<DonationSplit[]>([...row.splits]);
  const totalAmount = parseFloat(row.amount) || 0;
  const currentAllocated = splits.reduce((sum, s) => sum + (parseFloat(s.amount.toString()) || 0), 0);
  const remaining = totalAmount - currentAllocated;
  const isBalanced = Math.abs(remaining) < 0.01;

  const addSplit = () => {
    setSplits([...splits, { fund: Fund.General, amount: 0 }]);
  };

  const removeSplit = (idx: number) => {
    setSplits(splits.filter((_, i) => i !== idx));
  };

  const updateSplit = (idx: number, field: keyof DonationSplit, val: any) => {
    const newSplits = [...splits];
    newSplits[idx] = { ...newSplits[idx], [field]: val };
    setSplits(newSplits);
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-fade-in-up">
        <div className="bg-church-900 p-4 flex justify-between items-center text-white">
          <h3 className="font-bold text-lg flex items-center gap-2">
            <Layers className="w-5 h-5 text-church-gold" /> Designation Splits
          </h3>
          <button onClick={onClose}><X className="w-6 h-6" /></button>
        </div>

        <div className="p-6">
          <div className="flex justify-between items-end mb-4 border-b pb-2">
            <div>
              <p className="text-sm text-gray-500">Total Donation</p>
              <p className="text-2xl font-bold text-gray-800">${totalAmount.toFixed(2)}</p>
            </div>
            <div className={`text-right ${isBalanced ? 'text-green-600' : 'text-red-500'}`}>
              <p className="text-xs font-bold uppercase">Remaining to Allocate</p>
              <p className="text-xl font-bold">${remaining.toFixed(2)}</p>
            </div>
          </div>

          <div className="space-y-3 max-h-60 overflow-y-auto mb-4">
            {splits.map((split, idx) => (
              <div key={idx} className="flex gap-2 items-center">
                <select 
                  className="flex-1 p-2 rounded-xl border border-gray-200 bg-gray-50 text-sm"
                  value={split.fund}
                  onChange={(e) => updateSplit(idx, 'fund', e.target.value)}
                >
                  {Object.values(Fund).map(f => <option key={f} value={f}>{f}</option>)}
                </select>
                <div className="relative w-32">
                  <span className="absolute left-3 top-2 text-gray-400">$</span>
                  <input 
                    type="number" 
                    step="0.01"
                    className="w-full pl-6 p-2 rounded-xl border border-gray-200 bg-gray-50 font-bold"
                    value={split.amount}
                    onChange={(e) => updateSplit(idx, 'amount', parseFloat(e.target.value) || 0)}
                  />
                </div>
                <button onClick={() => removeSplit(idx)} className="p-2 text-red-400 hover:bg-red-50 rounded-lg">
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>

          <button onClick={addSplit} className="w-full py-2 border-2 border-dashed border-gray-300 rounded-xl text-gray-400 font-bold hover:border-church-500 hover:text-church-500 transition-colors mb-6">
            + Add Another Fund
          </button>

          <button 
            disabled={!isBalanced}
            onClick={() => onSave(splits)}
            className={`w-full py-3 rounded-xl font-bold flex items-center justify-center gap-2 ${isBalanced ? 'bg-church-900 text-white hover:bg-blue-800' : 'bg-gray-200 text-gray-400 cursor-not-allowed'}`}
          >
            <Check className="w-5 h-5" /> Confirm Splits
          </button>
        </div>
      </div>
    </div>
  );
};

const CashModal: React.FC<{ row: Row, onClose: () => void, onVerify: () => void }> = ({ row, onClose, onVerify }) => {
  const [counts, setCounts] = useState<Record<string, number>>({});

  const calculateTotal = () => {
    return DENOMINATIONS.reduce((sum, denom) => sum + (denom * (counts[denom] || 0)), 0);
  };

  const total = calculateTotal();
  const target = parseFloat(row.amount) || 0;
  const diff = total - target;
  const isMatch = Math.abs(diff) < 0.01;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl w-full max-w-2xl shadow-2xl overflow-hidden animate-fade-in-up flex flex-col max-h-[90vh]">
        <div className="bg-green-600 p-4 flex justify-between items-center text-white">
          <h3 className="font-bold text-lg flex items-center gap-2">
            <Calculator className="w-5 h-5 text-white" /> Cash Counter
          </h3>
          <button onClick={onClose}><X className="w-6 h-6" /></button>
        </div>

        <div className="p-6 overflow-y-auto flex-1">
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-4 mb-6">
             {DENOMINATIONS.map(denom => (
               <div key={denom} className="bg-gray-50 p-3 rounded-xl border border-gray-100 text-center">
                 <label className="text-xs font-bold text-gray-400 block mb-1">${denom}</label>
                 <input 
                   type="number"
                   min="0"
                   className="w-full p-1 bg-white border border-gray-200 rounded-lg text-center font-bold text-lg focus:ring-2 focus:ring-green-500 outline-none"
                   value={counts[denom] || ''}
                   onChange={(e) => setCounts({...counts, [denom]: parseInt(e.target.value) || 0})}
                   autoFocus={denom === 100}
                 />
               </div>
             ))}
          </div>

          <div className="bg-gray-50 p-6 rounded-2xl flex flex-col md:flex-row justify-between items-center gap-4">
             <div>
               <p className="text-sm text-gray-500 font-medium">Slip Amount</p>
               <p className="text-2xl font-bold text-gray-800">${target.toFixed(2)}</p>
             </div>
             <div className="hidden md:block text-gray-300 text-4xl font-light">/</div>
             <div className="text-center">
               <p className="text-sm text-gray-500 font-medium">Cash Counted</p>
               <p className="text-2xl font-bold text-church-900">${total.toFixed(2)}</p>
             </div>
             <div className="hidden md:block text-gray-300 text-4xl font-light">=</div>
             <div className={`px-6 py-2 rounded-xl text-center ${isMatch ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-600'}`}>
               <p className="text-xs font-bold uppercase">Difference</p>
               <p className="text-2xl font-bold">{diff > 0 ? '+' : ''}{diff.toFixed(2)}</p>
             </div>
          </div>
        </div>

        <div className="p-4 border-t bg-gray-50 flex justify-end gap-3">
           <button onClick={onClose} className="px-6 py-3 font-semibold text-gray-500 hover:bg-gray-200 rounded-xl transition-colors">Cancel</button>
           <button 
             onClick={onVerify}
             disabled={!isMatch}
             className={`px-8 py-3 font-bold rounded-xl flex items-center gap-2 ${isMatch ? 'bg-green-600 text-white hover:bg-green-700 shadow-lg' : 'bg-gray-300 text-gray-500 cursor-not-allowed'}`}
           >
             <Check className="w-5 h-5" /> Verify & Close
           </button>
        </div>
      </div>
    </div>
  );
};

export default BatchEntry;

import Dexie, { type Table } from 'dexie';
import { Giver, Batch, Donation, AppSettings } from '../types';

class ChurchDatabase extends Dexie {
  givers!: Table<Giver, number>;
  batches!: Table<Batch, number>;
  donations!: Table<Donation, number>;
  settings!: Table<AppSettings, number>;

  constructor() {
    super('SafeTrackDB');
    // Cast 'this' to any to avoid TS error: Property 'version' does not exist on type 'ChurchDatabase'
    (this as any).version(1).stores({
      givers: '++id, envelopeNumber, name',
      batches: '++id, batchNumber, date, status',
      donations: '++id, giverId, batchId, date',
      settings: '++id'
    });
  }
}

export const db = new ChurchDatabase();

// Initial Setup Helper
export const initDatabase = async () => {
  const count = await db.settings.count();
  if (count === 0) {
    await db.settings.add({ nextEnvelopeNumber: 100 });
  }
};

export const getNextEnvelopeNumber = async (): Promise<number> => {
  const setting = await db.settings.orderBy('id').first();
  return setting?.nextEnvelopeNumber || 100;
};

export const incrementEnvelopeNumber = async () => {
  const setting = await db.settings.orderBy('id').first();
  if (setting && setting.id) {
    await db.settings.update(setting.id, { nextEnvelopeNumber: setting.nextEnvelopeNumber + 1 });
  }
};

export const exportData = async (): Promise<string> => {
  const allGivers = await db.givers.toArray();
  const allBatches = await db.batches.toArray();
  const allDonations = await db.donations.toArray();
  const allSettings = await db.settings.toArray();

  return JSON.stringify({ givers: allGivers, batches: allBatches, donations: allDonations, settings: allSettings });
};

export const importData = async (jsonString: string) => {
  const data = JSON.parse(jsonString);
  // Cast 'db' to any to avoid TS error: Property 'transaction' does not exist on type 'ChurchDatabase'
  await (db as any).transaction('rw', db.givers, db.batches, db.donations, db.settings, async () => {
    await db.givers.clear();
    await db.batches.clear();
    await db.donations.clear();
    await db.settings.clear();

    if(data.givers) await db.givers.bulkAdd(data.givers);
    if(data.batches) await db.batches.bulkAdd(data.batches);
    if(data.donations) await db.donations.bulkAdd(data.donations);
    if(data.settings) await db.settings.bulkAdd(data.settings);
  });
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, getNextEnvelopeNumber, incrementEnvelopeNumber } from '../services/db';
import { Fund, PaymentMethod, BatchStatus, DonationSplit, Giver } from '../types';
import { Plus, Save, Trash2, AlertCircle, Layers, Calculator, X, Check, Banknote, Search, UserPlus, AlertTriangle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

// --- Types ---

interface Row {
  id: number;
  // Giver Data
  giverId?: number; 
  inputValue: string; // The text in the giver input
  // Financial Data
  amount: string;
  method: PaymentMethod;
  splits: DonationSplit[];
  // Cash Data
  cashCounts: Record<string, number>;
  // UI State
  error?: string;
}

const DENOMINATIONS = [100, 50, 20, 10, 5, 1, 0.25, 0.10, 0.05, 0.01];

// --- Helper Components ---

const GiverInput: React.FC<{
  rowId: number;
  value: string;
  onChange: (val: string) => void;
  onSelect: (giver: Giver | { id: number, name: string, envelopeNumber: number }) => void;
  onCreate: (name: string) => void;
  givers: Giver[];
  autoFocus?: boolean;
}> = ({ rowId, value, onChange, onSelect, onCreate, givers, autoFocus }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);

  // Filter logic
  const filtered = useMemo(() => {
    const term = value.toLowerCase();
    if (!term) return [];

    // Exact envelope match first
    const exactEnv = givers.filter(g => g.envelopeNumber.toString() === term);

    // Name matches or partial envelope matches
    const others = givers.filter(g => 
      (g.name.toLowerCase().includes(term) || g.envelopeNumber.toString().includes(term)) 
      && g.envelopeNumber.toString() !== term
    ).slice(0, 5); // Limit results

    return [...exactEnv, ...others];
  }, [value, givers]);

  const showCreateOption = value.length > 1 && !filtered.find(g => g.name.toLowerCase() === value.toLowerCase());

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIndex(prev => (prev + 1) % (filtered.length + (showCreateOption ? 1 : 0)));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex(prev => (prev - 1 + filtered.length + (showCreateOption ? 1 : 0)) % (filtered.length + (showCreateOption ? 1 : 0)));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (activeIndex < filtered.length) {
        onSelect(filtered[activeIndex]);
        setIsOpen(false);
      } else if (showCreateOption) {
        onCreate(value);
        setIsOpen(false);
      }
    } else if (e.key === 'Tab') {
      setIsOpen(false);
    }
  };

  // Handle "Loose Giving" specifically
  useEffect(() => {
    if (value === '0') {
      onSelect({ id: 0, name: 'Loose Giving', envelopeNumber: 0 });
    }
  }, [value]);

  return (
    <div className="relative w-full">
      <div className="relative">
        <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
        <input
          ref={inputRef}
          type="text"
          className="w-full pl-9 pr-3 py-2 rounded-lg border border-gray-200 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-church-500 outline-none text-sm font-medium"
          placeholder="Env # or Name"
          value={value}
          onChange={(e) => {
            onChange(e.target.value);
            setIsOpen(true);
            setActiveIndex(0);
          }}
          onFocus={() => setIsOpen(true)}
          onBlur={() => setTimeout(() => setIsOpen(false), 200)} // Delay to allow click
          onKeyDown={handleKeyDown}
          autoFocus={autoFocus}
        />
      </div>

      {isOpen && value && (filtered.length > 0 || showCreateOption) && (
        <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-xl shadow-2xl border border-gray-100 z-50 overflow-hidden">
          {filtered.map((g, idx) => (
            <div
              key={g.id}
              className={`px-4 py-2 cursor-pointer flex justify-between items-center ${idx === activeIndex ? 'bg-church-50' : 'hover:bg-gray-50'}`}
              onMouseDown={(e) => { e.preventDefault(); onSelect(g); setIsOpen(false); }}
            >
              <span className="font-bold text-gray-800">{g.name}</span>
              <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-500">#{g.envelopeNumber}</span>
            </div>
          ))}

          {showCreateOption && (
            <div
              className={`px-4 py-3 cursor-pointer flex items-center gap-2 text-church-500 font-bold border-t border-gray-100 ${activeIndex === filtered.length ? 'bg-church-50' : 'hover:bg-gray-50'}`}
              onMouseDown={(e) => { e.preventDefault(); onCreate(value); setIsOpen(false); }}
            >
              <UserPlus className="w-4 h-4" />
              Create "{value}"
            </div>
          )}
        </div>
      )}
    </div>
  );
};

// --- Main Component ---

const BatchEntry: React.FC = () => {
  const navigate = useNavigate();
  const allGivers = useLiveQuery(() => db.givers.toArray()) || [];

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [rows, setRows] = useState<Row[]>([
    { 
      id: Date.now(), 
      inputValue: '', 
      amount: '', 
      method: PaymentMethod.Check, 
      splits: [{ fund: Fund.General, amount: 0 }],
      cashCounts: {} 
    }
  ]);

  // Modals
  const [splitRowId, setSplitRowId] = useState<number | null>(null);
  const [cashRowId, setCashRowId] = useState<number | null>(null);
  const [quickAddName, setQuickAddName] = useState<string | null>(null);

  // --- Row Logic ---

  const addRow = () => {
    setRows(prev => [
      ...prev, 
      { 
        id: Date.now(), 
        inputValue: '', 
        amount: '', 
        method: PaymentMethod.Check, 
        splits: [{ fund: Fund.General, amount: 0 }],
        cashCounts: {}
      }
    ]);
  };

  const removeRow = (id: number) => {
    if (rows.length > 1) {
      setRows(rows.filter(r => r.id !== id));
    }
  };

  const updateRow = (id: number, updates: Partial<Row>) => {
    setRows(prev => prev.map(row => {
      if (row.id === id) {
        const updated = { ...row, ...updates, error: undefined };

        // Auto-update single split if amount changes
        if (updates.amount !== undefined) {
          const numAmount = parseFloat(updates.amount) || 0;
          if (updated.splits.length === 1) {
             updated.splits = [{ ...updated.splits[0], amount: numAmount }];
          }
        }
        return updated;
      }
      return row;
    }));
  };

  const handleGiverSelect = (rowId: number, giver: any) => {
    updateRow(rowId, { 
      giverId: giver.id, 
      inputValue: `${giver.name} (#${giver.envelopeNumber})` 
    });
  };

  const handleCreateGiverStart = (rowId: number, name: string) => {
    setQuickAddName(name); // Opens modal
    // Store rowId to update after creation? 
    // We'll use a ref or just find the row with matching inputValue or just last focused.
    // Better: pass the callback to the modal or use a transient state for "pending row".
    // Let's use a ref for the pending row ID.
    pendingRowRef.current = rowId;
  };
  const pendingRowRef = useRef<number | null>(null);

  const handleGiverCreated = (giver: Giver) => {
    if (pendingRowRef.current) {
      handleGiverSelect(pendingRowRef.current, giver);
      pendingRowRef.current = null;
    }
    setQuickAddName(null);
  };

  // --- Save Logic ---

  const calculateTotal = () => rows.reduce((sum, r) => sum + (parseFloat(r.amount) || 0), 0);

  const handleSave = async () => {
    const errors: string[] = [];
    rows.forEach((r, idx) => {
      if (!r.giverId && r.giverId !== 0) errors.push(`Row ${idx + 1}: No Giver selected.`);
      if (!parseFloat(r.amount)) errors.push(`Row ${idx + 1}: Amount is 0.`);

      const splitTotal = r.splits.reduce((sum, s) => sum + s.amount, 0);
      if (Math.abs(splitTotal - (parseFloat(r.amount) || 0)) > 0.01) {
        errors.push(`Row ${idx + 1}: Split amounts do not match total.`);
      }

      // Strict Cash Check? Optional, but let's warn if counts exist and don't match
      if (r.method === PaymentMethod.Cash) {
        const cashTotal = DENOMINATIONS.reduce((s, d) => s + (d * (r.cashCounts[d.toString()] || 0)), 0);
        if (cashTotal > 0 && Math.abs(cashTotal - (parseFloat(r.amount) || 0)) > 0.01) {
           errors.push(`Row ${idx + 1}: Cash denominations do not match slip amount.`);
        }
      }
    });

    if (errors.length > 0) {
      alert("Please fix the following errors:\n" + errors.join("\n"));
      return;
    }

    const batchId = await db.batches.add({
      batchNumber: `B-${Date.now()}`,
      date: date,
      status: BatchStatus.Open,
      totalAmount: calculateTotal(),
      itemCount: rows.length
    });

    for (const row of rows) {
      await db.donations.add({
        giverId: row.giverId!,
        batchId: batchId as number,
        amount: parseFloat(row.amount),
        date: date,
        paymentMethod: row.method,
        splits: row.splits
      });
    }

    navigate('/history');
  };

  const handleKeyDown = (e: React.KeyboardEvent, index: number) => {
    if (e.key === 'Tab' && !e.shiftKey && index === rows.length - 1) {
      const currentRow = rows[index];
      if (currentRow.inputValue && currentRow.amount) {
        addRow();
      }
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-bold text-gray-800">Smart Grid Entry</h2>
          <p className="text-gray-500">Rapidly process donations with inline tools.</p>
        </div>
        <div className="bg-church-900 text-white px-6 py-2 rounded-xl text-right shadow-lg">
          <p className="text-xs uppercase opacity-70">Batch Total</p>
          <p className="text-2xl font-bold">${calculateTotal().toFixed(2)}</p>
        </div>
      </div>

      {/* Grid Container */}
      <div className="bg-white p-4 rounded-3xl shadow-xl flex-1 flex flex-col overflow-hidden border border-gray-100">
        <div className="flex gap-4 mb-4 items-center border-b border-gray-100 pb-4">
          <label className="font-bold text-gray-700">Batch Date:</label>
          <input 
            type="date" 
            value={date} 
            onChange={(e) => setDate(e.target.value)}
            className="border-gray-200 border rounded-lg p-2 bg-gray-50 text-gray-800"
          />
        </div>

        <div className="flex-1 overflow-visible overflow-y-auto min-h-[300px] pb-32">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50 sticky top-0 z-40 text-gray-600">
              <tr>
                <th className="p-3 text-sm font-bold rounded-tl-xl w-1/3">Giver Lookup</th>
                <th className="p-3 text-sm font-bold w-32">Amount</th>
                <th className="p-3 text-sm font-bold w-40">Method</th>
                <th className="p-3 text-sm font-bold">Allocations</th>
                <th className="p-3 text-sm font-bold rounded-tr-xl w-16"></th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row, index) => {
                const isUnbalanced = Math.abs(row.splits.reduce((s, x) => s + x.amount, 0) - (parseFloat(row.amount) || 0)) > 0.01;
                const cashTotal = DENOMINATIONS.reduce((s, d) => s + (d * (row.cashCounts[d.toString()] || 0)), 0);
                const cashMismatch = row.method === PaymentMethod.Cash && cashTotal > 0 && Math.abs(cashTotal - (parseFloat(row.amount) || 0)) > 0.01;

                return (
                  <tr key={row.id} className="border-b border-gray-50 last:border-0 hover:bg-blue-50/30 transition-colors group align-top">
                    {/* Giver Search Column */}
                    <td className="p-2 relative z-10">
                      <GiverInput 
                        rowId={row.id}
                        value={row.inputValue}
                        onChange={(val) => updateRow(row.id, { inputValue: val, giverId: undefined })}
                        onSelect={(g) => handleGiverSelect(row.id, g)}
                        onCreate={(name) => handleCreateGiverStart(row.id, name)}
                        givers={allGivers}
                        autoFocus={index === rows.length - 1 && index > 0}
                      />
                    </td>

                    {/* Amount Column */}
                    <td className="p-2">
                      <div className="relative">
                        <span className="absolute left-3 top-2 text-gray-400 font-bold">$</span>
                        <input 
                          type="number"
                          step="0.01"
                          className={`w-full pl-6 p-2 rounded-lg border text-sm font-bold outline-none focus:ring-2 focus:ring-church-500 ${isUnbalanced ? 'border-red-300 bg-red-50 text-red-600' : 'border-gray-200 bg-gray-50 text-gray-800'}`}
                          value={row.amount}
                          onChange={(e) => updateRow(row.id, { amount: e.target.value })}
                          placeholder="0.00"
                        />
                      </div>
                    </td>

                    {/* Method Column */}
                    <td className="p-2">
                       <div className="flex gap-2">
                        <select 
                          className="flex-1 p-2 rounded-lg border border-gray-200 bg-gray-50 text-sm outline-none focus:ring-2 focus:ring-church-500"
                          value={row.method}
                          onChange={(e) => updateRow(row.id, { method: e.target.value as PaymentMethod })}
                        >
                          {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                        </select>

                        {/* Cash Details Button */}
                        {row.method === PaymentMethod.Cash && (
                          <button 
                            onClick={() => setCashRowId(row.id)}
                            className={`p-2 rounded-lg transition-colors border ${cashMismatch ? 'bg-red-100 text-red-500 border-red-200' : 'bg-gray-100 text-gray-400 hover:bg-church-100 hover:text-church-500 border-gray-200'}`}
                            title="Cash Denominations"
                            tabIndex={-1}
                          >
                            <Banknote className="w-4 h-4" />
                          </button>
                        )}
                       </div>
                    </td>

                    {/* Allocations (Split) Column */}
                    <td className="p-2">
                      <button 
                        onClick={() => setSplitRowId(row.id)}
                        onKeyDown={(e) => handleKeyDown(e, index)}
                        className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium border transition-all flex items-center justify-between outline-none focus:ring-2 focus:ring-church-500 ${
                          isUnbalanced 
                            ? 'bg-red-50 border-red-200 text-red-700' 
                            : 'bg-white border-gray-200 text-gray-600 hover:border-church-500'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          <Layers className="w-4 h-4 opacity-50" />
                          <span className="truncate">
                            {row.splits.length === 1 && row.splits[0].fund === Fund.General 
                              ? 'General Fund' 
                              : `${row.splits.length} Splits`}
                          </span>
                        </div>
                        {isUnbalanced ? <AlertCircle className="w-4 h-4" /> : <ChevronDown className="w-3 h-3 opacity-30"/>}
                      </button>
                    </td>

                    {/* Delete Action */}
                    <td className="p-2 text-center">
                      <button 
                        onClick={() => removeRow(row.id)}
                        className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        tabIndex={-1}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {/* Add Row Button (Bottom) */}
          <button 
            onClick={addRow}
            className="w-full mt-2 py-3 border-2 border-dashed border-gray-200 rounded-xl text-gray-400 font-bold hover:border-church-500 hover:text-church-500 transition-all flex justify-center items-center gap-2"
          >
            <Plus className="w-5 h-5" /> Add New Row
          </button>
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-gray-100 flex justify-end bg-gray-50 rounded-b-3xl mt-auto z-50 relative">
          <button 
            onClick={handleSave}
            className="bg-church-gold hover:bg-yellow-400 text-church-900 px-8 py-3 rounded-xl font-bold shadow-lg flex items-center gap-2 transition-transform active:scale-95"
          >
            <Save className="w-5 h-5" /> Save Batch to Vault
          </button>
        </div>
      </div>

      {/* --- Modals --- */}

      {quickAddName && (
        <QuickAddGiverModal 
          name={quickAddName} 
          onClose={() => setQuickAddName(null)} 
          onSave={handleGiverCreated} 
        />
      )}

      {splitRowId && (
        <SplitModal 
          row={rows.find(r => r.id === splitRowId)!} 
          onClose={() => setSplitRowId(null)}
          onSave={(splits) => {
             updateRow(splitRowId, { splits });
             setSplitRowId(null);
          }}
        />
      )}

      {cashRowId && (
        <CashModal 
          row={rows.find(r => r.id === cashRowId)!}
          onClose={() => setCashRowId(null)}
          onSave={(counts) => {
            updateRow(cashRowId, { cashCounts: counts });
            setCashRowId(null);
          }}
        />
      )}
    </div>
  );
};

