const SplitModal: React.FC<{ row: Row, onClose: () => void, onSave: (s: DonationSplit[]) => void }> = ({ row, onClose, onSave }) => {
  const [splits, setSplits] = useState<DonationSplit[]>([...row.splits]);
  const totalAmount = parseFloat(row.amount) || 0;

  // Recalculate remaining logic
  const currentAllocated = splits.reduce((sum, s) => sum + (parseFloat(s.amount.toString()) || 0), 0);
  const remaining = totalAmount - currentAllocated;
  const isBalanced = Math.abs(remaining) < 0.01;

  const updateSplit = (idx: number, field: keyof DonationSplit, val: any) => {
    const newSplits = [...splits];
    if (field === 'fund') {
         // Reset internal account if switching away from Internal
         if (val !== Fund.Internal) {
             delete (newSplits[idx] as any).internalAccount;
         }
    }
    newSplits[idx] = { ...newSplits[idx], [field]: val };
    setSplits(newSplits);
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-fade-in-up">
        <div className="bg-church-900 p-4 flex justify-between items-center text-white">
          <h3 className="font-bold text-lg flex items-center gap-2"><Layers className="w-5 h-5 text-church-gold" /> Designations</h3>
          <button onClick={onClose}><X className="w-6 h-6" /></button>
        </div>
        <div className="p-6">
          <div className="flex justify-between items-end mb-4 border-b pb-2">
            <div><p className="text-sm text-gray-500">Total Donation</p><p className="text-2xl font-bold text-gray-800">${totalAmount.toFixed(2)}</p></div>
            <div className={`text-right ${isBalanced ? 'text-green-600' : 'text-red-500'}`}>
              <p className="text-xs font-bold uppercase">Remaining</p><p className="text-xl font-bold">${remaining.toFixed(2)}</p>
            </div>
          </div>
          <div className="space-y-3 max-h-60 overflow-y-auto mb-4">
            {splits.map((split, idx) => (
              <div key={idx} className={`rounded-xl p-3 border transition-colors ${split.fund === Fund.Internal ? 'bg-blue-50/50 border-blue-200' : 'bg-gray-50 border-gray-100'}`}>
                <div className="flex gap-2 items-center">
                  <select className="flex-1 p-2 rounded-xl border border-gray-200 bg-white text-sm focus:ring-2 focus:ring-church-500 outline-none" value={split.fund} onChange={(e) => updateSplit(idx, 'fund', e.target.value)}>
                    {Object.values(Fund).map(f => <option key={f} value={f}>{f}</option>)}
                  </select>
                  <div className="relative w-32">
                    <span className="absolute left-3 top-2 text-gray-400">$</span>
                    <input type="number" step="0.01" className="w-full pl-6 p-2 rounded-xl border border-gray-200 bg-white font-bold focus:ring-2 focus:ring-church-500 outline-none" value={split.amount} onChange={(e) => updateSplit(idx, 'amount', parseFloat(e.target.value) || 0)} />
                  </div>
                  <button onClick={() => setSplits(splits.filter((_, i) => i !== idx))} className="p-2 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                </div>
                 {split.fund === Fund.Internal && (
                    <div className="mt-2 animate-fade-in">
                        <label className="text-xs font-bold text-gray-500 ml-1 mb-1 block">Internal Account Code</label>
                        <input 
                            type="text" 
                            maxLength={16}
                            placeholder="Enter 16-digit code"
                            className="w-full p-2 rounded-xl border border-gray-200 bg-white text-sm font-bold text-gray-800 focus:ring-2 focus:ring-church-500 outline-none uppercase transition-all placeholder:font-normal placeholder:text-gray-400 placeholder:normal-case"
                            value={split.internalAccount || ''}
                            onChange={(e) => updateSplit(idx, 'internalAccount', e.target.value)}
                        />
                    </div>
                 )}
              </div>
            ))}
          </div>
          <button onClick={() => setSplits([...splits, { fund: Fund.General, amount: 0 }])} className="w-full py-2 border-2 border-dashed border-gray-300 rounded-xl text-gray-400 font-bold hover:border-church-500 hover:text-church-500 transition-colors mb-6">+ Add Fund</button>
          <button disabled={!isBalanced} onClick={() => onSave(splits)} className={`w-full py-3 rounded-xl font-bold flex items-center justify-center gap-2 ${isBalanced ? 'bg-church-900 text-white' : 'bg-gray-200 text-gray-400 cursor-not-allowed'}`}><Check className="w-5 h-5" /> Confirm Splits</button>
        </div>
      </div>
    </div>
  );
};

const CashModal: React.FC<{ row: Row, onClose: () => void, onSave: (c: Record<string, number>) => void }> = ({ row, onClose, onSave }) => {
  const [counts, setCounts] = useState<Record<string, number>>({ ...row.cashCounts });
  const total = DENOMINATIONS.reduce((sum, d) => sum + (d * (counts[d.toString()] || 0)), 0);
  const target = parseFloat(row.amount) || 0;
  const diff = total - target;
  const isMatch = Math.abs(diff) < 0.01;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl w-full max-w-2xl shadow-2xl overflow-hidden animate-fade-in-up flex flex-col max-h-[90vh]">
        <div className="bg-green-600 p-4 flex justify-between items-center text-white">
          <h3 className="font-bold text-lg flex items-center gap-2"><Calculator className="w-5 h-5 text-white" /> Cash Counter</h3>
          <button onClick={onClose}><X className="w-6 h-6" /></button>
        </div>
        <div className="p-6 overflow-y-auto flex-1">
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-4 mb-6">
             {DENOMINATIONS.map(denom => (
               <div key={denom} className="bg-gray-50 p-3 rounded-xl border border-gray-100 text-center">
                 <label className="text-xs font-bold text-gray-400 block mb-1">${denom}</label>
                 <input type="number" min="0" className="w-full p-1 bg-white border border-gray-200 rounded-lg text-center font-bold text-lg focus:ring-2 focus:ring-green-500 outline-none" 
                   value={counts[denom] || ''} onChange={(e) => setCounts({...counts, [denom]: parseInt(e.target.value) || 0})} autoFocus={denom === 100} />
               </div>
             ))}
          </div>
          <div className="bg-gray-50 p-6 rounded-2xl flex flex-col md:flex-row justify-between items-center gap-4">
             <div><p className="text-sm text-gray-500 font-medium">Slip Amount</p><p className="text-2xl font-bold text-gray-800">${target.toFixed(2)}</p></div>
             <div className="hidden md:block text-gray-300 text-4xl font-light">/</div>
             <div className="text-center"><p className="text-sm text-gray-500 font-medium">Cash Counted</p><p className="text-2xl font-bold text-church-900">${total.toFixed(2)}</p></div>
             <div className="hidden md:block text-gray-300 text-4xl font-light">=</div>
             <div className={`px-6 py-2 rounded-xl text-center ${isMatch ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-600'}`}><p className="text-xs font-bold uppercase">Difference</p><p className="text-2xl font-bold">{diff > 0 ? '+' : ''}{diff.toFixed(2)}</p></div>
          </div>
        </div>
        <div className="p-4 border-t bg-gray-50 flex justify-end gap-3">
           <button onClick={onClose} className="px-6 py-3 font-semibold text-gray-500 hover:bg-gray-200 rounded-xl">Cancel</button>
           <button onClick={() => onSave(counts)} className="px-8 py-3 font-bold rounded-xl flex items-center gap-2 bg-green-600 text-white hover:bg-green-700 shadow-lg"><Check className="w-5 h-5" /> Save Counts</button>
        </div>
      </div>
    </div>
  );
};

export default BatchEntry;

import React, { useState, useEffect, useMemo } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db } from '../services/db';
import { BatchStatus, PaymentMethod } from '../types';
import { FileText, Lock, CheckCircle, Banknote, ScrollText, Unlock, AlertTriangle, X, ShieldAlert, Edit } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const BatchHistory: React.FC = () => {
  const navigate = useNavigate();
  const batches = useLiveQuery(() => db.batches.orderBy('date').reverse().toArray());
  const [selectedBatchId, setSelectedBatchId] = useState<number | null>(null);

  // Modals State
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [auditError, setAuditError] = useState<string | null>(null);

  // Fetch donations for the active batch for audit calculations
  const donations = useLiveQuery(() => 
    selectedBatchId ? db.donations.where('batchId').equals(selectedBatchId).toArray() : Promise.resolve([])
  , [selectedBatchId]);

  const activeBatch = batches?.find(b => b.id === selectedBatchId);

  // --- Audit State ---
  const [cashCounts, setCashCounts] = useState<Record<string, number>>({
    '100': 0, '50': 0, '20': 0, '10': 0, '5': 0, '1': 0, '0.25': 0, '0.10': 0, '0.05': 0, '0.01': 0
  });
  const [userCheckCount, setUserCheckCount] = useState<string>('');

  // Reset state on batch change
  useEffect(() => {
    setCashCounts({ '100': 0, '50': 0, '20': 0, '10': 0, '5': 0, '1': 0, '0.25': 0, '0.10': 0, '0.05': 0, '0.01': 0 });
    setUserCheckCount('');
    setShowConfirmModal(false);
    setAuditError(null);
  }, [selectedBatchId]);

  // --- Calculations ---

  // System Totals
  const systemCheckDonations = donations?.filter(d => d.paymentMethod === PaymentMethod.Check) || [];
  const systemCheckCount = systemCheckDonations.length;
  const systemCheckTotal = systemCheckDonations.reduce((sum, d) => sum + d.amount, 0);

  // Cash Calculations
  const systemCashTotal = donations?.filter(d => d.paymentMethod === PaymentMethod.Cash).reduce((sum, d) => sum + d.amount, 0) || 0;

  // Calculate System Denomination Counts (Aggregation)
  const DENOMINATIONS = [100, 50, 20, 10, 5, 1, 0.25, 0.10, 0.05, 0.01];
  const systemDenomCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    DENOMINATIONS.forEach(d => counts[d.toString()] = 0);

    donations?.forEach(d => {
      if (d.paymentMethod === PaymentMethod.Cash && d.cashCounts) {
        Object.entries(d.cashCounts).forEach(([denom, count]) => {
          counts[denom] = (counts[denom] || 0) + (count as number);
        });
      }
    });
    return counts;
  }, [donations]);

  // User Totals
  const countedCashTotal = Object.entries(cashCounts).reduce((acc, [denom, count]) => {
    return acc + (parseFloat(denom) * count);
  }, 0);

  // Variances
  const cashDiff = countedCashTotal - systemCashTotal;
  const isCashTotalBalanced = Math.abs(cashDiff) < 0.01;

  // Strict Denomination Check
  const countMismatches = DENOMINATIONS.filter(d => {
    const sys = systemDenomCounts[d.toString()] || 0;
    const usr = cashCounts[d.toString()] || 0;
    return sys !== usr;
  });
  const isCashCountsBalanced = countMismatches.length === 0;

  const isCashBalanced = isCashTotalBalanced && isCashCountsBalanced;

  const checkCountDiff = (parseInt(userCheckCount || '0')) - systemCheckCount;
  const isCheckBalanced = checkCountDiff === 0;

  const isReadyToFinalize = isCashBalanced && isCheckBalanced;

  // --- Actions ---

  const handleFinalizeClick = () => {
    if (!selectedBatchId) return;

    if (!isReadyToFinalize) {
      let errors = [];
      if (!isCashTotalBalanced) {
        errors.push(`Cash value variance of $${cashDiff.toFixed(2)} detected.`);
      } else if (!isCashCountsBalanced) {
        errors.push(`Cash value balanced, but denomination counts do not match expected system records.`);
      }

      if (!isCheckBalanced) errors.push(`Check count mismatch (Off by ${checkCountDiff > 0 ? '+' : ''}${checkCountDiff}).`);

      setAuditError(errors.join(' '));
      return;
    }

    setShowConfirmModal(true);
  };

  const executeFinalization = async () => {
    if (selectedBatchId) {
      try {
        await db.batches.update(selectedBatchId, { status: BatchStatus.Finalized });
        setShowConfirmModal(false);
      } catch (err) {
        console.error("Failed to finalize", err);
        setAuditError("System error occurred while updating batch.");
      }
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative">
      <h2 className="text-3xl font-bold text-gray-800">Batch History & Audit</h2>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 min-h-0">
        {/* Left: Batch List */}
        <div className="lg:col-span-4 space-y-4 overflow-y-auto max-h-[calc(100vh-12rem)] pr-2">
          {batches?.map(batch => (
            <div 
              key={batch.id} 
              onClick={() => setSelectedBatchId(batch.id || null)}
              className={`p-4 rounded-2xl cursor-pointer border transition-all ${
                selectedBatchId === batch.id 
                  ? 'bg-church-900 text-white shadow-xl scale-102 ring-2 ring-offset-2 ring-church-500' 
                  : 'bg-white hover:bg-blue-50 border-gray-200'
              }`}
            >
              <div className="flex justify-between items-center mb-2">
                <span className="font-bold">Batch #{batch.id}</span>
                <span className={`text-xs px-2 py-1 rounded-full font-bold ${
                  batch.status === BatchStatus.Finalized ? 'bg-green-400 text-green-900' : 'bg-yellow-400 text-yellow-900'
                }`}>
                  {batch.status}
                </span>
              </div>
              <div className="flex justify-between text-sm opacity-80">
                <span>{new Date(batch.date).toLocaleDateString()}</span>
                <span className="font-mono font-bold">${batch.totalAmount.toFixed(2)}</span>
              </div>
            </div>
          ))}
          {(!batches || batches.length === 0) && <p className="text-gray-400 text-center py-10">No batches found.</p>}
        </div>

        {/* Right: Audit & Details */}
        <div className="lg:col-span-8 bg-white rounded-3xl shadow-xl border border-gray-100 flex flex-col overflow-hidden">
          {activeBatch ? (
            <div className="flex flex-col h-full">
               {/* Header */}
               <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                 <div>
                   <h3 className="text-2xl font-bold text-gray-800">Batch #{activeBatch.id}</h3>
                   <div className="flex gap-4 text-sm mt-1">
                      <span className="text-gray-500">Date: <span className="font-semibold">{new Date(activeBatch.date).toLocaleDateString()}</span></span>
                      <span className="text-gray-500">Total: <span className="font-semibold text-church-900">${activeBatch.totalAmount.toFixed(2)}</span></span>
                   </div>
                 </div>

                 <div className="flex items-center gap-3">
                   {activeBatch.status === BatchStatus.Open ? (
                     <>
                      <button 
                        onClick={() => navigate(`/batch-entry?batchId=${activeBatch.id}`)}
                        className="flex items-center gap-2 px-4 py-3 rounded-xl font-bold bg-white border border-gray-200 text-gray-700 hover:bg-gray-100 shadow-sm transition-colors"
                      >
                        <Edit className="w-4 h-4" /> Edit Batch
                      </button>
                      <button 
                        onClick={handleFinalizeClick}
                        className={`flex items-center gap-2 px-6 py-3 rounded-xl shadow-lg transition-all font-bold ${
                          isReadyToFinalize 
                            ? 'bg-green-600 hover:bg-green-700 text-white animate-pulse' 
                            : 'bg-yellow-100 text-yellow-700 hover:bg-yellow-200 border border-yellow-300'
                        }`}
                      >
                        {isReadyToFinalize ? <Lock className="w-4 h-4" /> : <Unlock className="w-4 h-4" />}
                        {isReadyToFinalize ? 'Finalize Batch' : 'Audit Incomplete'}
                      </button>
                     </>
                   ) : (
                     <div className="flex items-center gap-2 text-green-700 bg-green-100 px-4 py-2 rounded-xl font-bold border border-green-200">
                       <CheckCircle className="w-5 h-5" /> Batch Locked
                     </div>
                   )}
                 </div>
               </div>

               {/* Audit Workspace */}
               <div className="flex-1 overflow-y-auto p-6 space-y-6">

                 {/* Cash Audit Section */}
                 <div className={`p-6 rounded-2xl border-2 transition-colors ${isCashBalanced ? 'bg-green-50/30 border-green-200' : 'bg-red-50/30 border-red-200'}`}>
                    <div className="flex justify-between items-center mb-4">
                      <h4 className="font-bold text-gray-700 flex items-center gap-2">
                        <Banknote className="w-5 h-5 text-church-500" /> Cash Audit
                      </h4>
                      <div className={`text-sm px-3 py-1 rounded-lg font-bold ${isCashBalanced ? 'text-green-700 bg-green-100' : 'text-red-600 bg-red-100'}`}>
                         {isCashBalanced 
                           ? 'Balanced' 
                           : (isCashTotalBalanced ? 'Count Mismatch' : `Variance: ${cashDiff > 0 ? '+' : ''}${cashDiff.toFixed(2)}`)
                         }
                      </div>
                    </div>

                    <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                      {DENOMINATIONS.map(denom => {
                        const sysCount = systemDenomCounts[denom.toString()] || 0;
                        const userCount = cashCounts[denom.toString()] || 0;
                        const match = sysCount === userCount;

                        return (
                          <div key={denom} className="relative">
                            <label className="text-xs font-bold text-gray-400 block mb-1 text-center">${denom}</label>
                            <input 
                              type="number" 
                              min="0"
                              disabled={activeBatch.status === BatchStatus.Finalized}
                              className={`w-full p-2 rounded-lg border text-center outline-none focus:ring-2 focus:ring-church-500 font-bold ${match ? 'bg-white border-gray-200 text-gray-800' : 'bg-red-50 border-red-300 text-red-600'}`}
                              value={cashCounts[denom.toString()] || ''}
                              onChange={(e) => setCashCounts({...cashCounts, [denom.toString()]: parseInt(e.target.value) || 0})}
                            />
                            {/* Expected Count Indicator if mismatch and strictly auditing */}
                            {(!match && activeBatch.status === BatchStatus.Open) && (
                              <div className="text-[10px] text-center text-gray-400 mt-1 font-medium">Exp: {sysCount}</div>
                            )}
                          </div>
                        );
                      })}
                    </div>

                    <div className="flex justify-between items-center mt-4 pt-4 border-t border-gray-200/50">
                       <div className="text-sm text-gray-500">System Recorded: <span className="font-bold">${systemCashTotal.toFixed(2)}</span></div>
                       <div className="text-lg text-gray-800">Counted: <span className="font-bold">${countedCashTotal.toFixed(2)}</span></div>
                    </div>
                 </div>

                 {/* Check Audit Section */}
