import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, getNextEnvelopeNumber, incrementEnvelopeNumber } from '../services/db';
import { Fund, PaymentMethod, BatchStatus, DonationSplit, Giver, Batch } from '../types';
import { Plus, Save, Trash2, AlertCircle, Layers, Calculator, X, Check, Banknote, Search, UserPlus, AlertTriangle, ChevronDown, ArrowLeft } from 'lucide-react';
import { useNavigate, useSearchParams } from 'react-router-dom';

// --- Types ---

interface Row {
  id: number; // React Key (timestamp or DB ID)
  donationId?: number; // DB ID if editing existing donation
  // Giver Data
  giverId?: number; 
  inputValue: string; // The text in the giver input
  // Financial Data
  amount: string;
  method: PaymentMethod;
  checkNumber: string;
  splits: DonationSplit[];
  // Cash Data
  cashCounts: Record<string, number>;
  // UI State
  error?: string;
}

const DENOMINATIONS = [100, 50, 20, 10, 5, 1, 0.25, 0.10, 0.05, 0.01];

// --- Helper Components ---

const GiverInput: React.FC<{
  rowId: number;
  value: string;
  onChange: (val: string) => void;
  onSelect: (giver: Giver | { id: number, name: string, name2?: string, envelopeNumber: number }) => void;
  onCreate: (name: string) => void;
  givers: Giver[];
  autoFocus?: boolean;
}> = ({ rowId, value, onChange, onSelect, onCreate, givers, autoFocus }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);

  // Filter logic
  const filtered = useMemo(() => {
    const term = value.toLowerCase();
    if (!term) return [];

    // Exact envelope match first
    const exactEnv = givers.filter(g => g.envelopeNumber.toString() === term);

    // Name, ID, or partial envelope matches
    const others = givers.filter(g => 
      (g.name.toLowerCase().includes(term) || 
       (g.name2 && g.name2.toLowerCase().includes(term)) ||
       (g.eTransferId && g.eTransferId.toLowerCase().includes(term)) ||
       (g.eTransferId2 && g.eTransferId2.toLowerCase().includes(term)) ||
       g.envelopeNumber.toString().includes(term)) 
      && g.envelopeNumber.toString() !== term
    ).slice(0, 5); // Limit results

    return [...exactEnv, ...others];
  }, [value, givers]);

  const showCreateOption = value.length > 1 && !filtered.find(g => g.name.toLowerCase() === value.toLowerCase());

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIndex(prev => (prev + 1) % (filtered.length + (showCreateOption ? 1 : 0)));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex(prev => (prev - 1 + filtered.length + (showCreateOption ? 1 : 0)) % (filtered.length + (showCreateOption ? 1 : 0)));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (activeIndex < filtered.length) {
        onSelect(filtered[activeIndex]);
        setIsOpen(false);
      } else if (showCreateOption) {
        onCreate(value);
        setIsOpen(false);
      }
    } else if (e.key === 'Tab') {
      setIsOpen(false);
    }
  };

  // Handle "Loose Giving" specifically
  useEffect(() => {
    if (value === '0') {
      onSelect({ id: 0, name: 'Loose Giving', envelopeNumber: 0 });
    }
  }, [value]);

  return (
    <div className="relative w-full">
      <div className="relative">
        <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
        <input
          ref={inputRef}
          type="text"
          className="w-full pl-9 pr-3 py-2 rounded-lg border border-gray-200 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-church-500 outline-none text-sm font-medium"
          placeholder="Env #, Name, or ID"
          value={value}
          onChange={(e) => {
            onChange(e.target.value);
            setIsOpen(true);
            setActiveIndex(0);
          }}
          onFocus={() => setIsOpen(true)}
          onBlur={() => setTimeout(() => setIsOpen(false), 200)} // Delay to allow click
          onKeyDown={handleKeyDown}
          autoFocus={autoFocus}
        />
      </div>

      {isOpen && value && (filtered.length > 0 || showCreateOption) && (
        <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-xl shadow-2xl border border-gray-100 z-50 overflow-hidden">
          {filtered.map((g, idx) => (
            <div
              key={g.id}
              className={`px-4 py-2 cursor-pointer flex justify-between items-center ${idx === activeIndex ? 'bg-church-50' : 'hover:bg-gray-50'}`}
              onMouseDown={(e) => { e.preventDefault(); onSelect(g); setIsOpen(false); }}
            >
              <div className="flex flex-col">
                <span className="font-bold text-gray-800">{g.name}</span>
                {g.name2 && <span className="text-xs text-church-500 font-medium">& {g.name2}</span>}
                {/* Show matched ID if applicable */}
                {g.eTransferId && g.eTransferId.toLowerCase().includes(value.toLowerCase()) && (
                  <span className="text-xs text-gray-400">Match: {g.eTransferId}</span>
                )}
                {g.eTransferId2 && g.eTransferId2.toLowerCase().includes(value.toLowerCase()) && (
                  <span className="text-xs text-gray-400">Match: {g.eTransferId2}</span>
                )}
              </div>
              <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-500">#{g.envelopeNumber}</span>
            </div>
          ))}

          {showCreateOption && (
            <div
              className={`px-4 py-3 cursor-pointer flex items-center gap-2 text-church-500 font-bold border-t border-gray-100 ${activeIndex === filtered.length ? 'bg-church-50' : 'hover:bg-gray-50'}`}
              onMouseDown={(e) => { e.preventDefault(); onCreate(value); setIsOpen(false); }}
            >
              <UserPlus className="w-4 h-4" />
              Create "{value}"
            </div>
          )}
        </div>
      )}
    </div>
  );
};

// --- Main Component ---

const BatchEntry: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const editBatchId = searchParams.get('batchId');

  const allGivers = useLiveQuery(() => db.givers.toArray()) || [];

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [editingBatch, setEditingBatch] = useState<Batch | null>(null);

  const [rows, setRows] = useState<Row[]>([
    { 
      id: Date.now(), 
      inputValue: '', 
      amount: '', 
      method: PaymentMethod.Check,
      checkNumber: '',
      splits: [{ fund: Fund.General, amount: 0 }],
      cashCounts: {} 
    }
  ]);

  const [deletedRowIds, setDeletedRowIds] = useState<number[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Modals
  const [splitRowId, setSplitRowId] = useState<number | null>(null);
  const [cashRowId, setCashRowId] = useState<number | null>(null);
  const [quickAddName, setQuickAddName] = useState<string | null>(null);

  // Load Batch Data if editing
  useEffect(() => {
    if (!editBatchId) {
      setIsLoaded(true);
      return;
    }

    const loadData = async () => {
      try {
        const bId = parseInt(editBatchId);
        const batch = await db.batches.get(bId);
        if (!batch) {
          alert("Batch not found");
          navigate('/history');
          return;
        }

        const donations = await db.donations.where('batchId').equals(bId).toArray();

        // Fetch givers to populate inputs
        const giverIds = [...new Set(donations.map(d => d.giverId))];
        const givers = await db.givers.bulkGet(giverIds);
        const giverMap = new Map(givers.filter(g => g !== undefined).map(g => [g!.id!, g!]));

        const loadedRows: Row[] = donations.map(d => {
          const g = giverMap.get(d.giverId);
          const nameDisplay = g ? (g.name2 ? `${g.name} & ${g.name2}` : g.name) : 'Unknown';
          const envDisplay = g ? g.envelopeNumber : '0';

          return {
            id: d.id!, // Use DB ID as key for existing rows
            donationId: d.id,
            giverId: d.giverId,
            inputValue: `${nameDisplay} (#${envDisplay})`,
            amount: d.amount.toString(),
            method: d.paymentMethod,
            checkNumber: d.checkNumber || '',
            splits: d.splits,
            cashCounts: d.cashCounts || {}
          };
        });

        setEditingBatch(batch);
        setDate(batch.date);
        setRows(loadedRows);
      } catch (e) {
        console.error("Failed to load batch", e);
      } finally {
        setIsLoaded(true);
      }
    };

    loadData();
  }, [editBatchId, navigate]);


  // --- Row Logic ---

  const addRow = () => {
    setRows(prev => [
      ...prev, 
      { 
        id: Date.now(), 
        inputValue: '', 
        amount: '', 
        method: PaymentMethod.Check, 
        checkNumber: '',
        splits: [{ fund: Fund.General, amount: 0 }],
        cashCounts: {}
      }
    ]);
  };

  const removeRow = (id: number) => {
    const row = rows.find(r => r.id === id);
    if (row && row.donationId) {
      setDeletedRowIds(prev => [...prev, row.donationId!]);
    }

    if (rows.length > 1 || rows.length === 1 && editBatchId) {
       // If editing, we allow deleting the last remaining row (to clear batch) 
       // but typically UI expects at least one. 
       // For better UX, if 1 row left and we remove it, maybe replace with empty?
       // Let's standard behavior: just remove. If 0 rows, add empty one or handle in validation.
       const newRows = rows.filter(r => r.id !== id);
       if (newRows.length === 0) {
         setRows([{ 
           id: Date.now(), inputValue: '', amount: '', method: PaymentMethod.Check, 
           checkNumber: '', splits: [{ fund: Fund.General, amount: 0 }], cashCounts: {} 
         }]);
       } else {
         setRows(newRows);
       }
    } else {
      // Create mode: don't delete last row, just clear it?
      setRows([{ 
           id: Date.now(), inputValue: '', amount: '', method: PaymentMethod.Check, 
           checkNumber: '', splits: [{ fund: Fund.General, amount: 0 }], cashCounts: {} 
      }]);
    }
  };

  const updateRow = (id: number, updates: Partial<Row>) => {
    setRows(prev => prev.map(row => {
      if (row.id === id) {
        const updated = { ...row, ...updates, error: undefined };

        // Auto-update single split if amount changes
        if (updates.amount !== undefined) {
          const numAmount = parseFloat(updates.amount) || 0;
          if (updated.splits.length === 1) {
             updated.splits = [{ ...updated.splits[0], amount: numAmount }];
          }
        }
        return updated;
      }
      return row;
    }));
  };

  const handleGiverSelect = (rowId: number, giver: Giver) => {
    const nameDisplay = giver.name2 ? `${giver.name} & ${giver.name2}` : giver.name;
    updateRow(rowId, { 
      giverId: giver.id, 
      inputValue: `${nameDisplay} (#${giver.envelopeNumber})` 
    });
  };

  const handleCreateGiverStart = (rowId: number, name: string) => {
    setQuickAddName(name); 
    pendingRowRef.current = rowId;
  };
  const pendingRowRef = useRef<number | null>(null);

  const handleGiverCreated = (giver: Giver) => {
    if (pendingRowRef.current) {
      handleGiverSelect(pendingRowRef.current, giver);
      pendingRowRef.current = null;
    }
    setQuickAddName(null);
  };

  // --- Save Logic ---

  const calculateTotal = () => rows.reduce((sum, r) => sum + (parseFloat(r.amount) || 0), 0);

  const handleSave = async () => {
    const errors: string[] = [];
    rows.forEach((r, idx) => {
      // Skip empty rows if they have no amount/giver (user might have added extra)
      if (!r.giverId && !r.amount && rows.length > 1) return;

      if (!r.giverId && r.giverId !== 0) errors.push(`Row ${idx + 1}: No Giver selected.`);
      if (!parseFloat(r.amount)) errors.push(`Row ${idx + 1}: Amount is 0.`);

      const splitTotal = r.splits.reduce((sum, s) => sum + s.amount, 0);
      if (Math.abs(splitTotal - (parseFloat(r.amount) || 0)) > 0.01) {
        errors.push(`Row ${idx + 1}: Split amounts do not match total.`);
      }

      if (r.method === PaymentMethod.Cash) {
        const cashTotal = DENOMINATIONS.reduce((s, d) => s + (d * (r.cashCounts[d.toString()] || 0)), 0);
        if (cashTotal > 0 && Math.abs(cashTotal - (parseFloat(r.amount) || 0)) > 0.01) {
           errors.push(`Row ${idx + 1}: Cash denominations do not match slip amount.`);
        }
      }
    });

    if (errors.length > 0) {
      alert("Please fix the following errors:\n" + errors.join("\n"));
      return;
    }

    try {
      if (editBatchId && editingBatch) {
        // --- UPDATE MODE ---
        await (db as any).transaction('rw', db.batches, db.donations, async () => {
           // 1. Update Batch Record
           await db.batches.update(editingBatch.id!, {
             date: date,
             totalAmount: calculateTotal(),
             itemCount: rows.length
           });

           // 2. Delete Removed Donations
           if (deletedRowIds.length > 0) {
             await db.donations.bulkDelete(deletedRowIds);
           }

           // 3. Upsert Rows
           for (const row of rows) {
             // Skip empty
             if (!row.giverId && !parseFloat(row.amount)) continue;

             const payload = {
                giverId: row.giverId!,
                batchId: editingBatch.id!,
                amount: parseFloat(row.amount),
                date: date,
                paymentMethod: row.method,
                checkNumber: row.method === PaymentMethod.Check ? row.checkNumber : undefined,
                splits: row.splits,
                cashCounts: row.method === PaymentMethod.Cash ? row.cashCounts : undefined
             };

             if (row.donationId) {
               await db.donations.update(row.donationId, payload);
             } else {
               await db.donations.add(payload);
             }
           }
        });
        navigate('/history');

      } else {
        // --- CREATE MODE ---
        const batchId = await db.batches.add({
          batchNumber: `B-${Date.now()}`,
          date: date,
          status: BatchStatus.Open,
          totalAmount: calculateTotal(),
          itemCount: rows.length
        });

        for (const row of rows) {
          if (!row.giverId && !parseFloat(row.amount)) continue;
          await db.donations.add({
            giverId: row.giverId!,
            batchId: batchId as number,
            amount: parseFloat(row.amount),
            date: date,
            paymentMethod: row.method,
            checkNumber: row.method === PaymentMethod.Check ? row.checkNumber : undefined,
            splits: row.splits,
            cashCounts: row.method === PaymentMethod.Cash ? row.cashCounts : undefined
          });
        }
        navigate('/history');
      }
    } catch (err) {
      console.error(err);
      alert("Failed to save batch. See console.");
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, index: number) => {
    if (e.key === 'Tab' && !e.shiftKey && index === rows.length - 1) {
      const currentRow = rows[index];
      if (currentRow.inputValue && currentRow.amount) {
        addRow();
      }
    }
  };

  if (!isLoaded) return <div className="p-8 text-center text-gray-500">Loading batch data...</div>;

  return (
    <div className="space-y-6 h-full flex flex-col relative">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
           {editBatchId ? (
             <div className="flex items-center gap-2">
                <button onClick={() => navigate('/history')} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                  <ArrowLeft className="w-5 h-5 text-gray-600" />
                </button>
                <div>
                  <h2 className="text-3xl font-bold text-gray-800">Edit Batch #{editBatchId}</h2>
                  <p className="text-gray-500">Modify donations, add records, or delete rows.</p>
                </div>
             </div>
           ) : (
             <div>
               <h2 className="text-3xl font-bold text-gray-800">New Batch Entry</h2>
               <p className="text-gray-500">Rapidly process donations with inline tools.</p>
             </div>
           )}
        </div>
        <div className="bg-church-900 text-white px-6 py-2 rounded-xl text-right shadow-lg">
          <p className="text-xs uppercase opacity-70">Batch Total</p>
          <p className="text-2xl font-bold">${calculateTotal().toFixed(2)}</p>
        </div>
      </div>

      {/* Grid Container */}
      <div className="bg-white p-4 rounded-3xl shadow-xl flex-1 flex flex-col overflow-hidden border border-gray-100">
        <div className="flex gap-4 mb-4 items-center border-b border-gray-100 pb-4">
          <label className="font-bold text-gray-700">Batch Date:</label>
          <input 
            type="date" 
            value={date} 
            onChange={(e) => setDate(e.target.value)}
            className="border-gray-200 border rounded-lg p-2 bg-gray-50 text-gray-800"
          />
        </div>

        <div className="flex-1 overflow-visible overflow-y-auto min-h-[300px] pb-32">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50 sticky top-0 z-40 text-gray-600">
              <tr>
                <th className="p-3 text-sm font-bold rounded-tl-xl w-1/3">Giver Lookup</th>
                <th className="p-3 text-sm font-bold w-32">Amount</th>
                <th className="p-3 text-sm font-bold w-48">Method</th>
                <th className="p-3 text-sm font-bold">Allocations</th>
                <th className="p-3 text-sm font-bold rounded-tr-xl w-16"></th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row, index) => {
                const isUnbalanced = Math.abs(row.splits.reduce((s, x) => s + x.amount, 0) - (parseFloat(row.amount) || 0)) > 0.01;
                const cashTotal = DENOMINATIONS.reduce((s, d) => s + (d * (row.cashCounts[d.toString()] || 0)), 0);
                const cashMismatch = row.method === PaymentMethod.Cash && cashTotal > 0 && Math.abs(cashTotal - (parseFloat(row.amount) || 0)) > 0.01;

                return (
                  <tr key={row.id} className="border-b border-gray-50 last:border-0 hover:bg-blue-50/30 transition-colors group align-top">
                    {/* Giver Search Column */}
                    <td className="p-2 relative z-10">
                      <GiverInput 
                        rowId={row.id}
                        value={row.inputValue}
                        onChange={(val) => updateRow(row.id, { inputValue: val, giverId: undefined })}
                        onSelect={(g) => handleGiverSelect(row.id, g)}
                        onCreate={(name) => handleCreateGiverStart(row.id, name)}
                        givers={allGivers}
                        autoFocus={index === rows.length - 1 && index > 0}
                      />
                    </td>

                    {/* Amount Column */}
                    <td className="p-2">
                      <div className="relative">
                        <span className="absolute left-3 top-2 text-gray-400 font-bold">$</span>
                        <input 
                          type="number"
                          step="0.01"
                          className={`w-full pl-6 p-2 rounded-lg border text-sm font-bold outline-none focus:ring-2 focus:ring-church-500 ${isUnbalanced ? 'border-red-300 bg-red-50 text-red-600' : 'border-gray-200 bg-gray-50 text-gray-800'}`}
                          value={row.amount}
                          onChange={(e) => updateRow(row.id, { amount: e.target.value })}
                          placeholder="0.00"
                        />
                      </div>
                    </td>

                    {/* Method Column */}
                    <td className="p-2">
                       <div className="flex gap-2">
                        <select 
                          className={`p-2 rounded-lg border border-gray-200 bg-gray-50 text-sm outline-none focus:ring-2 focus:ring-church-500 transition-all ${row.method === PaymentMethod.Check ? 'w-1/2' : 'flex-1'}`}
                          value={row.method}
                          onChange={(e) => updateRow(row.id, { method: e.target.value as PaymentMethod })}
                        >
                          {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                        </select>

                        {/* Check Number Input */}
                        {row.method === PaymentMethod.Check && (
                          <input 
                            type="text" 
                            placeholder="Chk #" 
                            className="w-1/2 p-2 rounded-lg border border-gray-200 bg-gray-50 text-sm outline-none focus:ring-2 focus:ring-church-500"
                            value={row.checkNumber}
                            onChange={(e) => updateRow(row.id, { checkNumber: e.target.value })}
                          />
                        )}

                        {/* Cash Details Button */}
                        {row.method === PaymentMethod.Cash && (
                          <button 
                            onClick={() => setCashRowId(row.id)}
                            className={`p-2 rounded-lg transition-colors border ${cashMismatch ? 'bg-red-100 text-red-500 border-red-200' : 'bg-gray-100 text-gray-400 hover:bg-church-100 hover:text-church-500 border-gray-200'}`}
                            title="Cash Denominations"
                            tabIndex={-1}
                          >
                            <Banknote className="w-4 h-4" />
                          </button>
                        )}
                       </div>
                    </td>

                    {/* Allocations (Split) Column */}
                    <td className="p-2">
                      <button 
                        onClick={() => setSplitRowId(row.id)}
                        onKeyDown={(e) => handleKeyDown(e, index)}
                        className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium border transition-all flex items-center justify-between outline-none focus:ring-2 focus:ring-church-500 ${
                          isUnbalanced 
                            ? 'bg-red-50 border-red-200 text-red-700' 
                            : 'bg-white border-gray-200 text-gray-600 hover:border-church-500'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          <Layers className="w-4 h-4 opacity-50" />
                          <span className="truncate">
                            {row.splits.length === 1 
                              ? (row.splits[0].fund === Fund.Internal 
                                  ? `Internal ${row.splits[0].internalAccount ? `(${row.splits[0].internalAccount})` : ''}` 
                                  : row.splits[0].fund)
                              : `${row.splits.length} Splits`}
                          </span>
                        </div>
                        {isUnbalanced ? <AlertCircle className="w-4 h-4" /> : <ChevronDown className="w-3 h-3 opacity-30"/>}
                      </button>
                    </td>

                    {/* Delete Action */}
                    <td className="p-2 text-center">
                      <button 
                        onClick={() => removeRow(row.id)}
                        className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        tabIndex={-1}
                        title="Delete Donation"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {/* Add Row Button (Bottom) */}
          <button 
            onClick={addRow}
            className="w-full mt-2 py-3 border-2 border-dashed border-gray-200 rounded-xl text-gray-400 font-bold hover:border-church-500 hover:text-church-500 transition-all flex justify-center items-center gap-2"
          >
            <Plus className="w-5 h-5" /> Add New Row
          </button>
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-gray-100 flex justify-end bg-gray-50 rounded-b-3xl mt-auto z-50 relative">
          <button 
            onClick={handleSave}
            className="bg-church-gold hover:bg-yellow-400 text-church-900 px-8 py-3 rounded-xl font-bold shadow-lg flex items-center gap-2 transition-transform active:scale-95"
          >
            <Save className="w-5 h-5" /> {editBatchId ? 'Update Batch' : 'Save Batch to Vault'}
          </button>
        </div>
      </div>

      {/* --- Modals --- */}

      {quickAddName && (
        <QuickAddGiverModal 
          name={quickAddName} 
          onClose={() => setQuickAddName(null)} 
          onSave={handleGiverCreated} 
        />
      )}

      {splitRowId && (
        <SplitModal 
          row={rows.find(r => r.id === splitRowId)!} 
          onClose={() => setSplitRowId(null)}
          onSave={(splits) => {
             updateRow(splitRowId, { splits });
             setSplitRowId(null);
          }}
        />
      )}

      {cashRowId && (
        <CashModal 
          row={rows.find(r => r.id === cashRowId)!}
          onClose={() => setCashRowId(null)}
          onSave={(counts) => {
            updateRow(cashRowId, { cashCounts: counts });
            setCashRowId(null);
          }}
        />
      )}
    </div>
  );
};

// --- Sub-Modals ---

const QuickAddGiverModal: React.FC<{ name: string, onClose: () => void, onSave: (g: Giver) => void }> = ({ name, onClose, onSave }) => {
  const [nextEnv, setNextEnv] = useState<number>(0);

  useEffect(() => {
    getNextEnvelopeNumber().then(setNextEnv);
  }, []);

  const handleConfirm = async () => {
    const id = await db.givers.add({
      envelopeNumber: nextEnv,
      name: name,
      email: '',
    });
    await incrementEnvelopeNumber();
    onSave({ id: id as number, envelopeNumber: nextEnv, name });
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-6 w-full max-w-sm shadow-2xl animate-fade-in-up">
        <h3 className="text-xl font-bold mb-4 text-gray-800">Quick Register Giver</h3>
        <div className="bg-blue-50 p-4 rounded-xl mb-4 text-center">
          <p className="text-xs font-bold text-church-900 uppercase">New Giver</p>
          <p className="text-xl font-bold text-gray-800">{name}</p>
          <p className="text-sm text-church-500 font-bold mt-1">Assigning Envelope #{nextEnv}</p>
        </div>
        <div className="flex gap-3">
          <button onClick={onClose} className="flex-1 py-2 text-gray-500 font-bold hover:bg-gray-100 rounded-xl">Cancel</button>
          <button onClick={handleConfirm} className="flex-1 py-2 bg-church-900 text-white font-bold rounded-xl hover:bg-blue-800">Confirm & Use</button>
        </div>
      </div>
    </div>
  );
};

const SplitModal: React.FC<{ row: Row, onClose: () => void, onSave: (s: DonationSplit[]) => void }> = ({ row, onClose, onSave }) => {
  const [splits, setSplits] = useState<DonationSplit[]>([...row.splits]);
  const totalAmount = parseFloat(row.amount) || 0;

  // Recalculate remaining logic
  const currentAllocated = splits.reduce((sum, s) => sum + (parseFloat(s.amount.toString()) || 0), 0);
  const remaining = totalAmount - currentAllocated;
  const isBalanced = Math.abs(remaining) < 0.01;

  const updateSplit = (idx: number, field: keyof DonationSplit, val: any) => {
    const newSplits = [...splits];
    if (field === 'fund') {
         // Reset internal account if switching away from Internal
         if (val !== Fund.Internal) {
             delete (newSplits[idx] as any).internalAccount;
         }
    }
    newSplits[idx] = { ...newSplits[idx], [field]: val };
    setSplits(newSplits);
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-fade-in-up">
        <div className="bg-church-900 p-4 flex justify-between items-center text-white">
          <h3 className="font-bold text-lg flex items-center gap-2"><Layers className="w-5 h-5 text-church-gold" /> Designations</h3>
          <button onClick={onClose}><X className="w-6 h-6" /></button>
        </div>
        <div className="p-6">
          <div className="flex justify-between items-end mb-4 border-b pb-2">
            <div><p className="text-sm text-gray-500">Total Donation</p><p className="text-2xl font-bold text-gray-800">${totalAmount.toFixed(2)}</p></div>
            <div className={`text-right ${isBalanced ? 'text-green-600' : 'text-red-500'}`}>
              <p className="text-xs font-bold uppercase">Remaining</p><p className="text-xl font-bold">${remaining.toFixed(2)}</p>
            </div>
          </div>
          <div className="space-y-3 max-h-60 overflow-y-auto mb-4">
            {splits.map((split, idx) => (
              <div key={idx} className={`rounded-xl p-3 border transition-colors ${split.fund === Fund.Internal ? 'bg-blue-50/50 border-blue-200' : 'bg-gray-50 border-gray-100'}`}>
                <div className="flex gap-2 items-center">
                  <select className="flex-1 p-2 rounded-xl border border-gray-200 bg-white text-sm focus:ring-2 focus:ring-church-500 outline-none" value={split.fund} onChange={(e) => updateSplit(idx, 'fund', e.target.value)}>
                    {Object.values(Fund).map(f => <option key={f} value={f}>{f}</option>)}
                  </select>
                  <div className="relative w-32">
                    <span className="absolute left-3 top-2 text-gray-400">$</span>
                    <input type="number" step="0.01" className="w-full pl-6 p-2 rounded-xl border border-gray-200 bg-white font-bold focus:ring-2 focus:ring-church-500 outline-none" value={split.amount} onChange={(e) => updateSplit(idx, 'amount', parseFloat(e.target.value) || 0)} />
                  </div>
                  <button onClick={() => setSplits(splits.filter((_, i) => i !== idx))} className="p-2 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                </div>
                 {split.fund === Fund.Internal && (
                    <div className="mt-2 animate-fade-in">
                        <label className="text-xs font-bold text-gray-500 ml-1 mb-1 block">Internal Account Code</label>
                        <input 
                            type="text" 
                            maxLength={16}
                            placeholder="Enter 16-digit code"
                            className="w-full p-2 rounded-xl border border-gray-200 bg-white text-sm font-bold text-gray-800 focus:ring-2 focus:ring-church-500 outline-none uppercase transition-all placeholder:font-normal placeholder:text-gray-400 placeholder:normal-case"
                            value={split.internalAccount || ''}
                            onChange={(e) => updateSplit(idx, 'internalAccount', e.target.value)}
                        />
                    </div>
                 )}
              </div>
            ))}
          </div>
          <button onClick={() => setSplits([...splits, { fund: Fund.General, amount: 0 }])} className="w-full py-2 border-2 border-dashed border-gray-300 rounded-xl text-gray-400 font-bold hover:border-church-500 hover:text-church-500 transition-colors mb-6">+ Add Fund</button>
          <button disabled={!isBalanced} onClick={() => onSave(splits)} className={`w-full py-3 rounded-xl font-bold flex items-center justify-center gap-2 ${isBalanced ? 'bg-church-900 text-white' : 'bg-gray-200 text-gray-400 cursor-not-allowed'}`}><Check className="w-5 h-5" /> Confirm Splits</button>
        </div>
      </div>
    </div>
  );
};

const CashModal: React.FC<{ row: Row, onClose: () => void, onSave: (c: Record<string, number>) => void }> = ({ row, onClose, onSave }) => {
  const [counts, setCounts] = useState<Record<string, number>>({ ...row.cashCounts });
  const total = DENOMINATIONS.reduce((sum, d) => sum + (d * (counts[d.toString()] || 0)), 0);
  const target = parseFloat(row.amount) || 0;
  const diff = total - target;
  const isMatch = Math.abs(diff) < 0.01;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl w-full max-w-2xl shadow-2xl overflow-hidden animate-fade-in-up flex flex-col max-h-[90vh]">
        <div className="bg-green-600 p-4 flex justify-between items-center text-white">
          <h3 className="font-bold text-lg flex items-center gap-2"><Calculator className="w-5 h-5 text-white" /> Cash Counter</h3>
          <button onClick={onClose}><X className="w-6 h-6" /></button>
        </div>
        <div className="p-6 overflow-y-auto flex-1">
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-4 mb-6">
             {DENOMINATIONS.map(denom => (
               <div key={denom} className="bg-gray-50 p-3 rounded-xl border border-gray-100 text-center">
                 <label className="text-xs font-bold text-gray-400 block mb-1">${denom}</label>
                 <input type="number" min="0" className="w-full p-1 bg-white border border-gray-200 rounded-lg text-center font-bold text-lg focus:ring-2 focus:ring-green-500 outline-none" 
                   value={counts[denom] || ''} onChange={(e) => setCounts({...counts, [denom]: parseInt(e.target.value) || 0})} autoFocus={denom === 100} />
               </div>
             ))}
          </div>
          <div className="bg-gray-50 p-6 rounded-2xl flex flex-col md:flex-row justify-between items-center gap-4">
             <div><p className="text-sm text-gray-500 font-medium">Slip Amount</p><p className="text-2xl font-bold text-gray-800">${target.toFixed(2)}</p></div>
             <div className="hidden md:block text-gray-300 text-4xl font-light">/</div>
             <div className="text-center"><p className="text-sm text-gray-500 font-medium">Cash Counted</p><p className="text-2xl font-bold text-church-900">${total.toFixed(2)}</p></div>
             <div className="hidden md:block text-gray-300 text-4xl font-light">=</div>
             <div className={`px-6 py-2 rounded-xl text-center ${isMatch ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-600'}`}><p className="text-xs font-bold uppercase">Difference</p><p className="text-2xl font-bold">{diff > 0 ? '+' : ''}{diff.toFixed(2)}</p></div>
          </div>
        </div>
        <div className="p-4 border-t bg-gray-50 flex justify-end gap-3">
           <button onClick={onClose} className="px-6 py-3 font-semibold text-gray-500 hover:bg-gray-200 rounded-xl">Cancel</button>
           <button onClick={() => onSave(counts)} className="px-8 py-3 font-bold rounded-xl flex items-center gap-2 bg-green-600 text-white hover:bg-green-700 shadow-lg"><Check className="w-5 h-5" /> Save Counts</button>
        </div>
      </div>
    </div>
  );
};

export default BatchEntry;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, getNextEnvelopeNumber, incrementEnvelopeNumber } from '../services/db';
import { Fund, PaymentMethod, BatchStatus, DonationSplit, Giver, Batch } from '../types';
import { Plus, Save, Trash2, AlertCircle, Layers, Calculator, X, Check, Banknote, Search, UserPlus, AlertTriangle, ChevronDown, ArrowLeft } from 'lucide-react';
import { useNavigate, useSearchParams } from 'react-router-dom';

// --- Types ---

interface Row {
  id: number; // React Key (timestamp or DB ID)
  donationId?: number; // DB ID if editing existing donation
  // Giver Data
  giverId?: number; 
  inputValue: string; // The text in the giver input
  // Financial Data
  amount: string;
  method: PaymentMethod;
  checkNumber: string;
  splits: DonationSplit[];
  // Cash Data
  cashCounts: Record<string, number>;
  // UI State
  error?: string;
}

const DENOMINATIONS = [100, 50, 20, 10, 5, 1, 0.25, 0.10, 0.05, 0.01];

// --- Helper Components ---

const GiverInput: React.FC<{
  rowId: number;
  value: string;
  onChange: (val: string) => void;
  onSelect: (giver: Giver | { id: number, name: string, name2?: string, envelopeNumber: number }) => void;
  onCreate: (name: string) => void;
  givers: Giver[];
  autoFocus?: boolean;
}> = ({ rowId, value, onChange, onSelect, onCreate, givers, autoFocus }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);

  // Filter logic
  const filtered = useMemo(() => {
    const term = value.toLowerCase();
    if (!term) return [];

    // Exact envelope match first
    const exactEnv = givers.filter(g => g.envelopeNumber.toString() === term);

    // Name, ID, or partial envelope matches
    const others = givers.filter(g => 
      (g.name.toLowerCase().includes(term) || 
       (g.name2 && g.name2.toLowerCase().includes(term)) ||
       (g.eTransferId && g.eTransferId.toLowerCase().includes(term)) ||
       (g.eTransferId2 && g.eTransferId2.toLowerCase().includes(term)) ||
       g.envelopeNumber.toString().includes(term)) 
      && g.envelopeNumber.toString() !== term
    ).slice(0, 5); // Limit results

    return [...exactEnv, ...others];
  }, [value, givers]);

  const showCreateOption = value.length > 1 && !filtered.find(g => g.name.toLowerCase() === value.toLowerCase());

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIndex(prev => (prev + 1) % (filtered.length + (showCreateOption ? 1 : 0)));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex(prev => (prev - 1 + filtered.length + (showCreateOption ? 1 : 0)) % (filtered.length + (showCreateOption ? 1 : 0)));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (activeIndex < filtered.length) {
        onSelect(filtered[activeIndex]);
        setIsOpen(false);
      } else if (showCreateOption) {
        onCreate(value);
        setIsOpen(false);
      }
    } else if (e.key === 'Tab') {
      setIsOpen(false);
    }
  };

  // Handle "Loose Giving" specifically
  useEffect(() => {
    if (value === '0') {
      onSelect({ id: 0, name: 'Loose Giving', envelopeNumber: 0 });
    }
  }, [value]);

  return (
    <div className="relative w-full">
      <div className="relative">
        <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
        <input
          ref={inputRef}
          type="text"
          className="w-full pl-9 pr-3 py-2 rounded-lg border border-gray-200 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-church-500 outline-none text-sm font-medium"
          placeholder="Env #, Name, or ID"
          value={value}
          onChange={(e) => {
            onChange(e.target.value);
            setIsOpen(true);
            setActiveIndex(0);
          }}
          onFocus={() => setIsOpen(true)}
          onBlur={() => setTimeout(() => setIsOpen(false), 200)} // Delay to allow click
          onKeyDown={handleKeyDown}
          autoFocus={autoFocus}
        />
      </div>

      {isOpen && value && (filtered.length > 0 || showCreateOption) && (
        <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-xl shadow-2xl border border-gray-100 z-50 overflow-hidden">
          {filtered.map((g, idx) => (
            <div
              key={g.id}
              className={`px-4 py-2 cursor-pointer flex justify-between items-center ${idx === activeIndex ? 'bg-church-50' : 'hover:bg-gray-50'}`}
              onMouseDown={(e) => { e.preventDefault(); onSelect(g); setIsOpen(false); }}
            >
              <div className="flex flex-col">
                <span className="font-bold text-gray-800">{g.name}</span>
                {g.name2 && <span className="text-xs text-church-500 font-medium">& {g.name2}</span>}
                {/* Show matched ID if applicable */}
                {g.eTransferId && g.eTransferId.toLowerCase().includes(value.toLowerCase()) && (
                  <span className="text-xs text-gray-400">Match: {g.eTransferId}</span>
                )}
                {g.eTransferId2 && g.eTransferId2.toLowerCase().includes(value.toLowerCase()) && (
                  <span className="text-xs text-gray-400">Match: {g.eTransferId2}</span>
                )}
              </div>
              <span className="text-xs font-mono bg-gray-100 px-2 py-1 rounded text-gray-500">#{g.envelopeNumber}</span>
            </div>
          ))}

          {showCreateOption && (
            <div
              className={`px-4 py-3 cursor-pointer flex items-center gap-2 text-church-500 font-bold border-t border-gray-100 ${activeIndex === filtered.length ? 'bg-church-50' : 'hover:bg-gray-50'}`}
              onMouseDown={(e) => { e.preventDefault(); onCreate(value); setIsOpen(false); }}
            >
              <UserPlus className="w-4 h-4" />
              Create "{value}"
            </div>
          )}
        </div>
      )}
    </div>
  );
};

// --- Main Component ---

const BatchEntry: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const editBatchId = searchParams.get('batchId');

  const allGivers = useLiveQuery(() => db.givers.toArray()) || [];

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [editingBatch, setEditingBatch] = useState<Batch | null>(null);

  const [rows, setRows] = useState<Row[]>([
    { 
      id: Date.now(), 
      inputValue: '', 
      amount: '', 
      method: PaymentMethod.Check,
      checkNumber: '',
      splits: [{ fund: Fund.General, amount: 0 }],
      cashCounts: {} 
    }
  ]);

  const [deletedRowIds, setDeletedRowIds] = useState<number[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Modals
  const [splitRowId, setSplitRowId] = useState<number | null>(null);
  const [cashRowId, setCashRowId] = useState<number | null>(null);
  const [quickAddName, setQuickAddName] = useState<string | null>(null);

  // Load Batch Data if editing
  useEffect(() => {
    if (!editBatchId) {
      setIsLoaded(true);
      return;
    }

    const loadData = async () => {
      try {
        const bId = parseInt(editBatchId);
        const batch = await db.batches.get(bId);
        if (!batch) {
          alert("Batch not found");
          navigate('/history');
          return;
        }

        const donations = await db.donations.where('batchId').equals(bId).toArray();

        // Fetch givers to populate inputs
        const giverIds = [...new Set(donations.map(d => d.giverId))];
        const givers = await db.givers.bulkGet(giverIds);

        const validGivers = givers.filter((g): g is Giver => !!g);
        const giverMap = new Map<number, Giver>(validGivers.map(g => [g.id!, g]));

        const loadedRows: Row[] = donations.map(d => {
          const g = giverMap.get(d.giverId);
          const nameDisplay = g ? (g.name2 ? `${g.name} & ${g.name2}` : g.name) : 'Unknown';
          const envDisplay = g ? g.envelopeNumber : '0';

          return {
            id: d.id!, // Use DB ID as key for existing rows
            donationId: d.id,
            giverId: d.giverId,
            inputValue: `${nameDisplay} (#${envDisplay})`,
            amount: d.amount.toString(),
            method: d.paymentMethod,
            checkNumber: d.checkNumber || '',
            splits: d.splits,
            cashCounts: d.cashCounts || {}
          };
        });

        setEditingBatch(batch);
        setDate(batch.date);
        setRows(loadedRows);
      } catch (e) {
        console.error("Failed to load batch", e);
      } finally {
        setIsLoaded(true);
      }
    };

    loadData();
  }, [editBatchId, navigate]);


  // --- Row Logic ---

  const addRow = () => {
    setRows(prev => [
      ...prev, 
      { 
        id: Date.now(), 
        inputValue: '', 
        amount: '', 
        method: PaymentMethod.Check, 
        checkNumber: '',
        splits: [{ fund: Fund.General, amount: 0 }],
        cashCounts: {}
      }
    ]);
  };

  const removeRow = (id: number) => {
    const row = rows.find(r => r.id === id);
    if (row && row.donationId) {
      setDeletedRowIds(prev => [...prev, row.donationId!]);
    }

    if (rows.length > 1 || rows.length === 1 && editBatchId) {
       // If editing, we allow deleting the last remaining row (to clear batch) 
       // but typically UI expects at least one. 
       // For better UX, if 1 row left and we remove it, maybe replace with empty?
       // Let's standard behavior: just remove. If 0 rows, add empty one or handle in validation.
       const newRows = rows.filter(r => r.id !== id);
       if (newRows.length === 0) {
         setRows([{ 
           id: Date.now(), inputValue: '', amount: '', method: PaymentMethod.Check, 
           checkNumber: '', splits: [{ fund: Fund.General, amount: 0 }], cashCounts: {} 
         }]);
       } else {
         setRows(newRows);
       }
    } else {
      // Create mode: don't delete last row, just clear it?
      setRows([{ 
           id: Date.now(), inputValue: '', amount: '', method: PaymentMethod.Check, 
           checkNumber: '', splits: [{ fund: Fund.General, amount: 0 }], cashCounts: {} 
      }]);
    }
  };

  const updateRow = (id: number, updates: Partial<Row>) => {
    setRows(prev => prev.map(row => {
      if (row.id === id) {
        const updated = { ...row, ...updates, error: undefined };

        // Auto-update single split if amount changes
        if (updates.amount !== undefined) {
          const numAmount = parseFloat(updates.amount) || 0;
          if (updated.splits.length === 1) {
             updated.splits = [{ ...updated.splits[0], amount: numAmount }];
          }
        }
        return updated;
      }
      return row;
    }));
  };

  const handleGiverSelect = (rowId: number, giver: Giver) => {
    const nameDisplay = giver.name2 ? `${giver.name} & ${giver.name2}` : giver.name;
    updateRow(rowId, { 
      giverId: giver.id, 
      inputValue: `${nameDisplay} (#${giver.envelopeNumber})` 
    });
  };

  const handleCreateGiverStart = (rowId: number, name: string) => {
    setQuickAddName(name); 
    pendingRowRef.current = rowId;
  };
  const pendingRowRef = useRef<number | null>(null);

  const handleGiverCreated = (giver: Giver) => {
    if (pendingRowRef.current) {
      handleGiverSelect(pendingRowRef.current, giver);
      pendingRowRef.current = null;
    }
    setQuickAddName(null);
  };

  // --- Save Logic ---

  const calculateTotal = () => rows.reduce((sum, r) => sum + (parseFloat(r.amount) || 0), 0);

  const handleSave = async () => {
    const errors: string[] = [];
    rows.forEach((r, idx) => {
      // Skip empty rows if they have no amount/giver (user might have added extra)
      if (!r.giverId && !r.amount && rows.length > 1) return;

      if (!r.giverId && r.giverId !== 0) errors.push(`Row ${idx + 1}: No Giver selected.`);
      if (!parseFloat(r.amount)) errors.push(`Row ${idx + 1}: Amount is 0.`);

      const splitTotal = r.splits.reduce((sum, s) => sum + s.amount, 0);
      if (Math.abs(splitTotal - (parseFloat(r.amount) || 0)) > 0.01) {
        errors.push(`Row ${idx + 1}: Split amounts do not match total.`);
      }

      if (r.method === PaymentMethod.Cash) {
        const cashTotal = DENOMINATIONS.reduce((s, d) => s + (d * (r.cashCounts[d.toString()] || 0)), 0);
        if (cashTotal > 0 && Math.abs(cashTotal - (parseFloat(r.amount) || 0)) > 0.01) {
           errors.push(`Row ${idx + 1}: Cash denominations do not match slip amount.`);
        }
      }
    });

    if (errors.length > 0) {
      alert("Please fix the following errors:\n" + errors.join("\n"));
      return;
    }

    try {
      if (editBatchId && editingBatch) {
        // --- UPDATE MODE ---
        await (db as any).transaction('rw', db.batches, db.donations, async () => {
           // 1. Update Batch Record
           await db.batches.update(editingBatch.id!, {
             date: date,
             totalAmount: calculateTotal(),
             itemCount: rows.length
           });

           // 2. Delete Removed Donations
           if (deletedRowIds.length > 0) {
             await db.donations.bulkDelete(deletedRowIds);
           }

           // 3. Upsert Rows
           for (const row of rows) {
             // Skip empty
             if (!row.giverId && !parseFloat(row.amount)) continue;

             const payload = {
                giverId: row.giverId!,
                batchId: editingBatch.id!,
                amount: parseFloat(row.amount),
                date: date,
                paymentMethod: row.method,
                checkNumber: row.method === PaymentMethod.Check ? row.checkNumber : undefined,
                splits: row.splits,
                cashCounts: row.method === PaymentMethod.Cash ? row.cashCounts : undefined
             };

             if (row.donationId) {
               await db.donations.update(row.donationId, payload);
             } else {
               await db.donations.add(payload);
             }
           }
        });
        navigate('/history');

      } else {
        // --- CREATE MODE ---
        const batchId = await db.batches.add({
          batchNumber: `B-${Date.now()}`,
          date: date,
          status: BatchStatus.Open,
          totalAmount: calculateTotal(),
          itemCount: rows.length
        });

        for (const row of rows) {
          if (!row.giverId && !parseFloat(row.amount)) continue;
          await db.donations.add({
            giverId: row.giverId!,
            batchId: batchId as number,
            amount: parseFloat(row.amount),
            date: date,
            paymentMethod: row.method,
            checkNumber: row.method === PaymentMethod.Check ? row.checkNumber : undefined,
            splits: row.splits,
            cashCounts: row.method === PaymentMethod.Cash ? row.cashCounts : undefined
          });
        }
        navigate('/history');
      }
    } catch (err) {
      console.error(err);
      alert("Failed to save batch. See console.");
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent, index: number) => {
    if (e.key === 'Tab' && !e.shiftKey && index === rows.length - 1) {
      const currentRow = rows[index];
      if (currentRow.inputValue && currentRow.amount) {
        addRow();
      }
    }
  };

  if (!isLoaded) return <div className="p-8 text-center text-gray-500">Loading batch data...</div>;

  return (
    <div className="space-y-6 h-full flex flex-col relative">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
           {editBatchId ? (
             <div className="flex items-center gap-2">
                <button onClick={() => navigate('/history')} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                  <ArrowLeft className="w-5 h-5 text-gray-600" />
                </button>
                <div>
                  <h2 className="text-3xl font-bold text-gray-800">Edit Batch #{editBatchId}</h2>
                  <p className="text-gray-500">Modify donations, add records, or delete rows.</p>
                </div>
             </div>
           ) : (
             <div>
               <h2 className="text-3xl font-bold text-gray-800">New Batch Entry</h2>
               <p className="text-gray-500">Rapidly process donations with inline tools.</p>
             </div>
           )}
        </div>
        <div className="bg-church-900 text-white px-6 py-2 rounded-xl text-right shadow-lg">
          <p className="text-xs uppercase opacity-70">Batch Total</p>
          <p className="text-2xl font-bold">${calculateTotal().toFixed(2)}</p>
        </div>
      </div>

      {/* Grid Container */}
      <div className="bg-white p-4 rounded-3xl shadow-xl flex-1 flex flex-col overflow-hidden border border-gray-100">
        <div className="flex gap-4 mb-4 items-center border-b border-gray-100 pb-4">
          <label className="font-bold text-gray-700">Batch Date:</label>
          <input 
            type="date" 
            value={date} 
            onChange={(e) => setDate(e.target.value)}
            className="border-gray-200 border rounded-lg p-2 bg-gray-50 text-gray-800"
          />
        </div>

        <div className="flex-1 overflow-visible overflow-y-auto min-h-[300px] pb-32">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50 sticky top-0 z-40 text-gray-600">
              <tr>
                <th className="p-3 text-sm font-bold rounded-tl-xl w-1/3">Giver Lookup</th>
                <th className="p-3 text-sm font-bold w-32">Amount</th>
                <th className="p-3 text-sm font-bold w-48">Method</th>
                <th className="p-3 text-sm font-bold">Allocations</th>
                <th className="p-3 text-sm font-bold rounded-tr-xl w-16"></th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row, index) => {
                const isUnbalanced = Math.abs(row.splits.reduce((s, x) => s + x.amount, 0) - (parseFloat(row.amount) || 0)) > 0.01;
                const cashTotal = DENOMINATIONS.reduce((s, d) => s + (d * (row.cashCounts[d.toString()] || 0)), 0);
                const cashMismatch = row.method === PaymentMethod.Cash && cashTotal > 0 && Math.abs(cashTotal - (parseFloat(row.amount) || 0)) > 0.01;

                return (
                  <tr key={row.id} className="border-b border-gray-50 last:border-0 hover:bg-blue-50/30 transition-colors group align-top">
                    {/* Giver Search Column */}
                    <td className="p-2 relative z-10">
                      <GiverInput 
                        rowId={row.id}
                        value={row.inputValue}
                        onChange={(val) => updateRow(row.id, { inputValue: val, giverId: undefined })}
                        onSelect={(g) => handleGiverSelect(row.id, g)}
                        onCreate={(name) => handleCreateGiverStart(row.id, name)}
                        givers={allGivers}
                        autoFocus={index === rows.length - 1 && index > 0}
                      />
                    </td>

                    {/* Amount Column */}
                    <td className="p-2">
                      <div className="relative">
                        <span className="absolute left-3 top-2 text-gray-400 font-bold">$</span>
                        <input 
                          type="number"
                          step="0.01"
                          className={`w-full pl-6 p-2 rounded-lg border text-sm font-bold outline-none focus:ring-2 focus:ring-church-500 ${isUnbalanced ? 'border-red-300 bg-red-50 text-red-600' : 'border-gray-200 bg-gray-50 text-gray-800'}`}
                          value={row.amount}
                          onChange={(e) => updateRow(row.id, { amount: e.target.value })}
                          placeholder="0.00"
                        />
                      </div>
                    </td>

                    {/* Method Column */}
                    <td className="p-2">
                       <div className="flex gap-2">
                        <select 
                          className={`p-2 rounded-lg border border-gray-200 bg-gray-50 text-sm outline-none focus:ring-2 focus:ring-church-500 transition-all ${row.method === PaymentMethod.Check ? 'w-1/2' : 'flex-1'}`}
                          value={row.method}
                          onChange={(e) => updateRow(row.id, { method: e.target.value as PaymentMethod })}
                        >
                          {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                        </select>

                        {/* Check Number Input */}
                        {row.method === PaymentMethod.Check && (
                          <input 
                            type="text" 
                            placeholder="Chk #" 
                            className="w-1/2 p-2 rounded-lg border border-gray-200 bg-gray-50 text-sm outline-none focus:ring-2 focus:ring-church-500"
                            value={row.checkNumber}
                            onChange={(e) => updateRow(row.id, { checkNumber: e.target.value })}
                          />
                        )}

                        {/* Cash Details Button */}
                        {row.method === PaymentMethod.Cash && (
                          <button 
                            onClick={() => setCashRowId(row.id)}
                            className={`p-2 rounded-lg transition-colors border ${cashMismatch ? 'bg-red-100 text-red-500 border-red-200' : 'bg-gray-100 text-gray-400 hover:bg-church-100 hover:text-church-500 border-gray-200'}`}
                            title="Cash Denominations"
                            tabIndex={-1}
                          >
                            <Banknote className="w-4 h-4" />
                          </button>
                        )}
                       </div>
                    </td>

                    {/* Allocations (Split) Column */}
                    <td className="p-2">
                      <button 
                        onClick={() => setSplitRowId(row.id)}
                        onKeyDown={(e) => handleKeyDown(e, index)}
                        className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium border transition-all flex items-center justify-between outline-none focus:ring-2 focus:ring-church-500 ${
                          isUnbalanced 
                            ? 'bg-red-50 border-red-200 text-red-700' 
                            : 'bg-white border-gray-200 text-gray-600 hover:border-church-500'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          <Layers className="w-4 h-4 opacity-50" />
                          <span className="truncate">
                            {row.splits.length === 1 
                              ? (row.splits[0].fund === Fund.Internal 
                                  ? `Internal ${row.splits[0].internalAccount ? `(${row.splits[0].internalAccount})` : ''}` 
                                  : row.splits[0].fund)
                              : `${row.splits.length} Splits`}
                          </span>
                        </div>
                        {isUnbalanced ? <AlertCircle className="w-4 h-4" /> : <ChevronDown className="w-3 h-3 opacity-30"/>}
                      </button>
                    </td>

                    {/* Delete Action */}
                    <td className="p-2 text-center">
                      <button 
                        onClick={() => removeRow(row.id)}
                        className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                        tabIndex={-1}
                        title="Delete Donation"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {/* Add Row Button (Bottom) */}
          <button 
            onClick={addRow}
            className="w-full mt-2 py-3 border-2 border-dashed border-gray-200 rounded-xl text-gray-400 font-bold hover:border-church-500 hover:text-church-500 transition-all flex justify-center items-center gap-2"
          >
            <Plus className="w-5 h-5" /> Add New Row
          </button>
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-gray-100 flex justify-end bg-gray-50 rounded-b-3xl mt-auto z-50 relative">
          <button 
            onClick={handleSave}
            className="bg-church-gold hover:bg-yellow-400 text-church-900 px-8 py-3 rounded-xl font-bold shadow-lg flex items-center gap-2 transition-transform active:scale-95"
          >
            <Save className="w-5 h-5" /> {editBatchId ? 'Update Batch' : 'Save Batch to Vault'}
          </button>
        </div>
      </div>

      {/* --- Modals --- */}

      {quickAddName && (
        <QuickAddGiverModal 
          name={quickAddName} 
          onClose={() => setQuickAddName(null)} 
          onSave={handleGiverCreated} 
        />
      )}

      {splitRowId && (
        <SplitModal 
          row={rows.find(r => r.id === splitRowId)!} 
          onClose={() => setSplitRowId(null)}
          onSave={(splits) => {
             updateRow(splitRowId, { splits });
             setSplitRowId(null);
          }}
        />
      )}

      {cashRowId && (
        <CashModal 
          row={rows.find(r => r.id === cashRowId)!}
          onClose={() => setCashRowId(null)}
          onSave={(counts) => {
            updateRow(cashRowId, { cashCounts: counts });
            setCashRowId(null);
          }}
        />
      )}
    </div>
  );
};

// --- Sub-Modals ---

const QuickAddGiverModal: React.FC<{ name: string, onClose: () => void, onSave: (g: Giver) => void }> = ({ name, onClose, onSave }) => {
  const [nextEnv, setNextEnv] = useState<number>(0);

  useEffect(() => {
    getNextEnvelopeNumber().then(setNextEnv);
  }, []);

  const handleConfirm = async () => {
    const id = await db.givers.add({
      envelopeNumber: nextEnv,
      name: name,
      email: '',
    });
    await incrementEnvelopeNumber();
    onSave({ id: id as number, envelopeNumber: nextEnv, name });
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-6 w-full max-w-sm shadow-2xl animate-fade-in-up">
        <h3 className="text-xl font-bold mb-4 text-gray-800">Quick Register Giver</h3>
        <div className="bg-blue-50 p-4 rounded-xl mb-4 text-center">
          <p className="text-xs font-bold text-church-900 uppercase">New Giver</p>
          <p className="text-xl font-bold text-gray-800">{name}</p>
          <p className="text-sm text-church-500 font-bold mt-1">Assigning Envelope #{nextEnv}</p>
        </div>
        <div className="flex gap-3">
          <button onClick={onClose} className="flex-1 py-2 text-gray-500 font-bold hover:bg-gray-100 rounded-xl">Cancel</button>
          <button onClick={handleConfirm} className="flex-1 py-2 bg-church-900 text-white font-bold rounded-xl hover:bg-blue-800">Confirm & Use</button>
        </div>
      </div>
    </div>
  );
};

const SplitModal: React.FC<{ row: Row, onClose: () => void, onSave: (s: DonationSplit[]) => void }> = ({ row, onClose, onSave }) => {
  const [splits, setSplits] = useState<DonationSplit[]>([...row.splits]);
  const totalAmount = parseFloat(row.amount) || 0;

  // Recalculate remaining logic
  const currentAllocated = splits.reduce((sum, s) => sum + (parseFloat(s.amount.toString()) || 0), 0);
  const remaining = totalAmount - currentAllocated;
  const isBalanced = Math.abs(remaining) < 0.01;

  const updateSplit = (idx: number, field: keyof DonationSplit, val: any) => {
    const newSplits = [...splits];
    if (field === 'fund') {
         // Reset internal account if switching away from Internal
         if (val !== Fund.Internal) {
             delete (newSplits[idx] as any).internalAccount;
         }
    }
    newSplits[idx] = { ...newSplits[idx], [field]: val };
    setSplits(newSplits);
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-fade-in-up">
        <div className="bg-church-900 p-4 flex justify-between items-center text-white">
          <h3 className="font-bold text-lg flex items-center gap-2"><Layers className="w-5 h-5 text-church-gold" /> Designations</h3>
          <button onClick={onClose}><X className="w-6 h-6" /></button>
        </div>
        <div className="p-6">
          <div className="flex justify-between items-end mb-4 border-b pb-2">
            <div><p className="text-sm text-gray-500">Total Donation</p><p className="text-2xl font-bold text-gray-800">${totalAmount.toFixed(2)}</p></div>
            <div className={`text-right ${isBalanced ? 'text-green-600' : 'text-red-500'}`}>
              <p className="text-xs font-bold uppercase">Remaining</p><p className="text-xl font-bold">${remaining.toFixed(2)}</p>
            </div>
          </div>
          <div className="space-y-3 max-h-60 overflow-y-auto mb-4">
            {splits.map((split, idx) => (
              <div key={idx} className={`rounded-xl p-3 border transition-colors ${split.fund === Fund.Internal ? 'bg-blue-50/50 border-blue-200' : 'bg-gray-50 border-gray-100'}`}>
                <div className="flex gap-2 items-center">
                  <select className="flex-1 p-2 rounded-xl border border-gray-200 bg-white text-sm focus:ring-2 focus:ring-church-500 outline-none" value={split.fund} onChange={(e) => updateSplit(idx, 'fund', e.target.value)}>
                    {Object.values(Fund).map(f => <option key={f} value={f}>{f}</option>)}
                  </select>
                  <div className="relative w-32">
                    <span className="absolute left-3 top-2 text-gray-400">$</span>
                    <input type="number" step="0.01" className="w-full pl-6 p-2 rounded-xl border border-gray-200 bg-white font-bold focus:ring-2 focus:ring-church-500 outline-none" value={split.amount} onChange={(e) => updateSplit(idx, 'amount', parseFloat(e.target.value) || 0)} />
                  </div>
                  <button onClick={() => setSplits(splits.filter((_, i) => i !== idx))} className="p-2 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 className="w-4 h-4" /></button>
                </div>
                 {split.fund === Fund.Internal && (
                    <div className="mt-2 animate-fade-in">
                        <label className="text-xs font-bold text-gray-500 ml-1 mb-1 block">Internal Account Code</label>
                        <input 
                            type="text" 
                            maxLength={16}
                            placeholder="Enter 16-digit code"
                            className="w-full p-2 rounded-xl border border-gray-200 bg-white text-sm font-bold text-gray-800 focus:ring-2 focus:ring-church-500 outline-none uppercase transition-all placeholder:font-normal placeholder:text-gray-400 placeholder:normal-case"
                            value={split.internalAccount || ''}
                            onChange={(e) => updateSplit(idx, 'internalAccount', e.target.value)}
                        />
                    </div>
                 )}
              </div>
            ))}
